programs.sol:
"""A sparse approximation of several text-formatting responses.

URL query punctuation is strongly negative, including short parameter names split
from their question marks. Dynamic web pages give a larger response than static
files or opaque resource IDs. New user turns, closing HTML/SVG roots, and
compound words ending in 'field' give positive responses. Other rules cover
small header conventions and middle-dot padding. Document-initial tokens
get coarse character-shape offsets; other text is nearly zero.
"""
import re

READS = ()
URI = re.compile(r'[A-Za-z][A-Za-z0-9+.-]*://[^\s<>]*$')


def query_strength(before):
    """Recognize a URL/path endpoint, and estimate its question-mark response."""
    fragment = re.split(r'''[\s"'<>`]''', before)[-1]
    is_uri = bool(URI.search(before) or re.search(r'www\.[^\s<>]*$', before))
    path = fragment.split('?', 1)[0]
    # Require web-path syntax, not an algebraic fraction such as x/y.
    is_path = bool(re.fullmatch(
        r'/(?:[\w.~%-]+/)*[A-Za-z_][\w.~%-]{1,}', path
    ) or re.fullmatch(
        r'[\w-]*\.(?:php|asp|aspx|htm|html|js|png|jpg|tsx|mdx|css|db)',
        path
    ) or re.search(r'(?:[\w-]+\.)+[a-z]{2,6}/', path))
    if not (is_uri or is_path):
        return None
    endpoint = path.rsplit('/', 1)[-1]
    if endpoint.endswith(('.php', '.asp', '.aspx')):
        return 12.5
    if endpoint.endswith(('.js', '.png', '.jpg', '.tsx', '.mdx')):
        return 5.0
    if len(endpoint) > 20 and any(c.isdigit() for c in endpoint):
        return 4.0
    return 8.2 if is_uri else 6.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    fresh = carry is None or carry[0] != doc
    before, ended = ('', False) if fresh else carry[1:]
    value = -0.003
    if fresh:
        word = token.strip()
        value = 0.11
        if not word:
            value = 0.16
        elif word.isdecimal():
            value = 0.15
        elif word.isalpha():
            value = (0.32 if word[0].isupper() else 0.17) \
                if word.isascii() else 0.25
        if token == '<|im_start|>':
            value = 0.247

    query_before = before + '/' if token.startswith('/?') else before
    strength = query_strength(query_before) if '?' in token else None
    if strength is not None and token.startswith(('?', '/?')):
        value = -strength
        if token.startswith('/?'):
            value = -6.0
        elif token.startswith('?family') and before.endswith('/css'):
            value = -13.0
    elif token.startswith('&') and '?' in before and query_strength(before):
        value = -6.5 if token.startswith('&q') else -4.5
        if token.startswith('&w'):
            value = -1.9
    elif before.endswith('?') and token.isalpha():
        strength = query_strength(before[:-1])
        if strength:
            value = -4.5 if len(token) <= 2 else -1.5
            if token == 'title' and before.endswith('index.php?'):
                value = -12.0
    elif token == '\n' and before.endswith('<|im_start|>user'):
        value = 0.385 if ended else 0.111
    elif token == ' b' and before.endswith('+++'):
        value = -2.23
    elif token == ' a' and before.endswith('---'):
        value = -0.81
    elif token == 'field' and before[-1:].isalpha():
        value = 1.78
    elif token.lower() == 'ix' and before.lower().endswith('append'):
        value = 1.2
    elif token == ' Tags' and before.endswith('Show'):
        value = -1.61
    elif token in ('html', 'svg') and before.endswith('</'):
        value = 2.8
    elif token == 'html' and before.endswith('```'):
        value = 1.2
    elif token == 'latex' and re.search(r'class=[\'\"]$', before):
        value = 2.8
    elif token == ':' and before == 'Title':
        value = 1.934
    elif len(token) >= 2 and set(token) == {'·'}:
        value = -0.7

    ended = ended or '<|im_end|>' in token
    return (doc, (before + token)[-512:], ended), float(value)

"""A partial spelling-context predictor for h-centred word pieces.

Training examples suggest positive hash, sheaf/sheath, heave and behave
continuations, but negative mathematical/th continuations and Hungarian
-hat/-het/-ít endings. These are spelling rules, not topic classifiers.

Recent accents and function words provide a persistent Hungarian hint.
Small additional rules cover Russian схем-, Arabic h+a, Greek theta+a,
and a document-initial Title: field. Unmatched positions return zero;
the rules do not explain the component's remaining low-level variation.
"""
import re

READS = ()


def predict(previous, token, recent, initial, known_hungarian=False):
    p, t = previous.lower(), token.lower()
    if initial and p == 'title' and t == ':':
        return -6.55
    if 'hash' in t:
        return 0.52
    if p.endswith('h') and t.startswith('ash'):
        return 1.8

    # Hungarian ability suffixes and the causative -ít ending.
    suffix = (t in ('hat', 'het', 'hatt', 'et', 'ets', 'at', 'ats') or
              p.endswith('í') or p in ('hat', 'het'))
    hungarian = suffix and (known_hungarian or
                           any(c in 'őű' for c in recent))
    if hungarian:
        if t in ('hat', 'het', 'hatt') and p[-1:].isalpha():
            return -5.3
        if p.endswith('h') and t in ('et', 'ets', 'at', 'ats'):
            return -5.5
        if p.endswith('í') and t in ('t', 'th', 'tm', 'ts', 'tt'):
            return -2.0
        if p in ('hat', 'het') and t and t[:1] in 'óő':
            return -2.0

    if known_hungarian and t in (' hat', ' het'):
        return -1.7
    if p.endswith('х') and t == 'ем':
        return 2.1  # Russian схем-, the scheme/diagram stem.

    if p.endswith('math'):
        if t == 'ematic':
            return -5.0
        if t == 'emat':
            return -1.4
        if t in ('.min', '.max'):
            return -3.0
        if t == '.abs':
            return -0.9
    if p.endswith('beh') and t in ('at', 'av'):
        return 4.3
    if p.endswith('be') and t in ('have', 'having', 'hat'):
        return 4.0
    if p.endswith('he'):
        if t == 'af' or (p.endswith('she') and t == 'aves'):
            return 7.8
        if t in ('ave', 'aves', 'aving'):
            return 4.2
        if t == 'athing':
            return 6.0
        if t in ('ath', 'aths', 'ather'):
            return 1.8
        if t in ('ap', 'app', 'aped', 'ep'):
            return 2.0
    if p.endswith('th'):
        if t == 'ät':
            return -6.6
        if t in ('et', 'ets', 'ek', 'eks'):
            return -1.1
        if re.match(r'^a[bcfmpt]|^em', t):
            return -1.0
    if p.endswith('ph') and t == 'atic':
        return -2.2
    if p.endswith('h') and re.match(r'^(att|et|aff)', t):
        return -0.65
    if p.endswith('sh') and t in ('am', 'aw', 'ave', 'aving'):
        return 0.65
    if p.endswith('ه') and t == 'ا':
        return 1.4
    if p.endswith('θ') and t == 'α':
        return -1.4
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, count, hungarian = '', '', 0, False
    else:
        _, previous, recent, count, hungarian = carry
    token = prefix.token_strings[-1]
    value = predict(previous, token, recent, count == 1, hungarian)
    recent = (recent + token)[-160:]
    # Once reliable language cues appear, retain them for this document.
    hungarian = hungarian or any(c in 'őű' for c in token)
    if (any(c in 'áéíóú' for c in token) and
            sum(c in 'áéíóú' for c in recent) >= 3 and
            any(w in recent for w in (' és ', ' nem ', ' egy ', ' hogy '))):
        hungarian = True
    return (doc, token, recent, count + 1, hungarian), value

"""Number-group openings, especially zeros in round monetary amounts.

Look at commas after numbers and at the first two following digits. The
response is stronger for money, round amounts, and numbers beginning after
whitespace; a spaced list separator is weaker. Also recognize quantitative
uses of 'of', with opposite signs for magnitudes and plural durations.
Also respond at adjacent citation brackets and East Asian counting/measure
heads after numerals. Everything else is near zero. Keep a short text suffix.
"""
import re
import unicodedata
import wordnet
from functools import lru_cache

READS = ()
# Single-token heads of counting suffixes and measurement expressions.
MEASURE_HEADS = set("重種分週家名元万億倍つか公")


# Approximation and bound words immediately before a written amount.
AMOUNT_CUES = set("about around approximately roughly nearly over under than "
                  "least most estimated of".split())
DURATIONS = set("second minute hour day week month year decade century "
                "millennium".split())


@lru_cache(maxsize=4096)
def quantified(word):
    return (word.isdecimal() or wordnet.is_a(word, 'integer') or
            word in {'some', 'several', 'many', 'few', 'all', 'large',
                     'vast', 'huge', 'significant'})


@lru_cache(maxsize=4096)
def quantity_of(word, modifier):
    forms = wordnet.base_forms(word)
    plural = word.endswith('s')
    count = quantified(modifier)
    article = modifier in {'a', 'an'}
    if word == 'orders' or (word == 'order' and (count or article)):
        return 4.0
    if any(w in {'ten', 'hundred', 'thousand', 'million', 'billion', 'trillion'}
           for w in forms):
        return 2.2 if plural else 1.5
    if word in {'rest', 'remainder'}:
        return 0.7
    if word == 'total':
        return 2.2 if article else 0.6
    if word in {'average', 'mean', 'median', 'maximum', 'minimum', 'sum', 'sums'}:
        return 1.2 if article or count else 0.4
    if plural and any(w in DURATIONS for w in forms):
        return -0.6
    if wordnet.is_a(word, 'mass unit') or wordnet.is_a(word, 'volume unit'):
        return 1.2 if count else 0.25
    if wordnet.is_a(word, 'kind'):
        return 1.1 if count else 0.05
    if wordnet.is_a(word, 'quantity'):
        return 0.9 if count and word != 'number' else 0.03
    return 0.0


def preceding_amount(text):
    char = text[-1:]
    word = re.search(r'([A-Za-z]+)\s*\Z', text)
    return (char in ('$', '£', '€', '¥', '₹'),
            not text or char.isspace(),
            bool(word and word[1].lower() in AMOUNT_CUES))


def group_digits(number, before, digit):
    """Amplitudes for the first, second and third digits of a group."""
    money, spaced, cue = preceding_amount(before)
    zero = digit == '0'
    if money:
        first, second = (11.0, 4.3) if zero else (6.0, 2.0)
    elif zero:
        if len(number) == 1:
            first = 3.7 if spaced else 1.0
        elif number.endswith('0'):
            first = 8.6 if spaced else 5.9
        else:
            first = 4.0
        second = 2.9 if spaced else 1.4
    else:
        first, second = (3.2, 1.0) if spaced else (1.0, 0.5)
    if number == '0' and not money:
        first = -0.5 if before.endswith(',') else 0.2
    if cue and number != '0' and len(number) <= 3 and not money:
        first += 3.0 if zero else 1.5
        second += 0.7
    return first, second, -0.13 if zero else -0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    digit = len(token) == 1 and token in '0123456789'
    if digit:
        m = re.search(r'([0-9]+)(, |,|\xa0)([0-9]{0,2})\Z', text)
        if m:
            number, separator, tail = m.groups()
            if separator == ', ':
                value = 0.2 if not tail else 0.0
            else:
                value = group_digits(number, text[:m.start()], token)[len(tail)]
    elif token == ',':
        m = re.search(r'([0-9]+)\Z', text)
        if m:
            number = m[1]
            before = text[:m.start()]
            money, spaced, cue = preceding_amount(before)
            if money:
                value = 2.7
            elif before.endswith(','):
                value = 1.6 if len(number) == 3 else -0.25
            elif spaced:
                value = 0.0 if number == '0' else 0.4 if len(number) == 1 else 0.72
            else:
                value = 0.15 if len(number) > 1 else 0.0
            if cue and number != '0':
                value += 1.1
            if len(number) > 3:
                value = 0.12
    elif token in {'][', ',['}:
        citation = re.search(r'\[[0-9, \]\[]+\Z', text)
        if citation:
            value = 0.5 if '][' in citation[0] else 3.8
    elif (token.strip() in MEASURE_HEADS and text
          and unicodedata.numeric(text[-1], None) is not None):
        value = 2.0
    elif token.lower() == ' of':
        m = re.search(r'([A-Za-z]+)\Z', text)
        if m:
            modifier = re.search(r'([A-Za-z]+|[0-9]+)\s*\Z', text[:m.start()])
            value = quantity_of(m[1].lower(), modifier[1].lower() if modifier else '')
        elif re.search(r'[0-9]\Z', text):
            value = 0.6
    return (doc, (text + token)[-100:]), value

"""Approximate a material/ingredient signal and related spelling responses.

Chinese 料 and 材, material/ingredient words, and anticipation phrases are
negative responses. Related spellings in French, Vietnamese and Korean also
fire; larger pieces of words are distinguished from split characters.
料 has both a material sense and an anticipation sense, hence both groups.
The first colon of a document headed 'Title:' is a separate strong response.
Small case/number offsets approximate document-initial effects. Elsewhere,
unmatched tokens predict zero. Short text and unfinished UTF-8 bytes are
carried forward and reset at each new document.
"""
import codecs

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, pending, number = '', b'', 0
    else:
        _, tail, pending, number = carry
    token = prefix.token_strings[-1]
    decoder = codecs.getincrementaldecoder('utf-8')('replace')
    decoder.setstate((pending, 0))
    text = decoder.decode(prefix.token_bytes[-1])
    pending = decoder.getstate()[0]
    word = text.strip()
    before = tail.lower()
    value = 0.0

    # Material, ingredient and information compounds, including Japanese uses.
    if word == '料':
        value = -4.0
        if '\ufffd' in token:
            value = -7.5
        elif before.endswith(('有', '無', '意', '怎')):
            value = -5.7
        elif before.endswith('调味'):
            value = -2.6
        elif before.endswith('資'):
            value = -1.6
    elif '原料' in word:
        value = -4.8
    elif '材料' in word:
        value = -3.1
        if not tail.rstrip(' \t').split('\n')[-1]:
            value = -4.8
    elif word in ('预料', '預料'):
        value = -2.0
    elif word.endswith(('想到', '想不到')):
        value = -1.5
        if before.endswith(('没', '沒')):
            value = -2.8
    elif word in ('到', '到了', '知') and before.endswith('料'):
        value = -3.0
    elif word == '燃料':
        value = -1.0
    elif word == '资料':
        value = -2.0
    elif word == '資料':
        value = -0.9
    elif word == '配料':
        value = -3.0
    elif word in ('调料', '調料', '史料'):
        value = -1.3
    elif word == '料理':
        value = -0.5
    elif word == '材':
        value = -1.6
    elif word == '食材':
        value = -1.5
    elif word in ('素材', '题材', '題材'):
        value = -0.8
    elif '粮' in word or '糧' in word:
        value = -3.5 if len(word) == 1 else -1.7
    elif word.lower() == 'materials':
        value = -0.65 if text.startswith(' ') else -2.1
        if before.rstrip().endswith(' raw'):
            value -= 1.4
    elif text == 'les' and before.endswith('materia'):
        value = -2.4
    elif text in ('s', 'S') and before.endswith('material'):
        value = -1.9
    elif word.lower() == 'material' and before.rstrip().endswith(' raw'):
        value = -1.5
    elif word.lower() == 'ingredients':
        value = -0.6
    elif word.lower().startswith('материал'):
        value = -0.7
    elif (word in ('ов', 'ами', 'ы', 'ам', 'ом')
          and before.endswith(('материал', 'миллион'))):
        value = -1.3
    elif word in ('ал', 'ала') and before.endswith('матери'):
        value = -1.5

    # Similar spellings and translations in French, Vietnamese and Korean.
    elif word in ('lieu', 'milieu'):
        value = -2.1 if word == 'lieu' else -1.55
    elif word in ('ieu', 'ieux'):
        value = -3.8 if before.endswith('l') else -0.8
        if word == 'ieux':
            value = -0.6
    elif text.lower() in ('u', 'ux') and before.endswith(('ie', 'ia', 'á')):
        value = 0.0 if before.endswith('die') else -2.6
        if text.lower() == 'ux':
            value = -3.0 if before.endswith('lie') else -0.9
            if before.endswith('matéria'):
                value = -4.3
    elif text == 'u' and before.endswith('li'):
        value = -2.3
    elif text == 'ou' and before.endswith('li'):
        value = -1.3
    elif text == 'iu' and before.endswith('l'):
        value = -1.2
    elif text.lower() in ('au', 'ao', 'iao') and before.endswith(('l', 'y', 'q')):
        value = -1.2
    elif word.lower() == 'liệu':
        value = -3.5
        if before.rstrip().endswith('dữ'):
            value = -0.9
        elif before.rstrip().endswith(('vật', 'dược')):
            value = -2.6
        elif before.rstrip().endswith(('xem', 'biết')):
            value = -7.5
    elif word == 'ệu':
        value = -11.0 if before.endswith('li') else -0.9
        if before.endswith('tri'):
            value = -3.5
    elif word in ('ếc', 'êu') and before.endswith('li'):
        value = -5.0 if word == 'ếc' else -3.0
    elif word == '료':
        value = -3.8 if before.endswith('자') else -0.6
        if before.endswith(('음', '연')):
            value = -3.0
        if before.endswith('의'):
            value = -2.0

    # Small document-initial offsets from broad character classes.
    if number == 0 and value == 0.0:
        if text.startswith('<|'):
            value = -0.4
        elif word.isascii() and word.isdigit():
            value = 0.2
        elif word.isascii() and word.isalpha():
            value = 0.33 if len(word) == 1 and word.isupper() else 0.12

    if word == ':' and number == 1 and tail == 'Title':
        value = -5.12
    return (doc, (tail + text)[-40:], pending, number + 1), value

programs.haiku:
"""Negative activation on words for 'material / supplies / ingredients', mainly in Chinese.

The component's activation is negative on the token that completes such a word:
料 (material, fee, feed; the most reliable), 材 and 材料 (material), 原料, 资料, 食材, 粮,
the Vietnamese 'liệu' (material), the English 'materials' / 'ingredients', and the French
'lieu' / 'milieu' tokens. Everywhere else the prediction is 0 (the component is near 0).
Values are roughly half the typical activation, the scale that best fits the data.
"""

READS = ()

SCALE = 0.5


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    if tok.endswith("料"):
        value = -3.9
    elif tok.endswith("粮"):
        value = -4.0
    elif tok.endswith("材") or tok.endswith("材料"):
        value = -2.0
    elif "liệu" in tok or tok == "ệu":
        value = -4.0
    elif tok in ("ieu", "lieu", "milieu", "ieux"):
        value = -2.4
    elif "material" in tok:
        value = -0.7
    elif "ingredient" in tok:
        value = -0.6
    else:
        value = 0.0
    return None, SCALE * value

programs.sol:
"""A noun-phrase boundary approximation, not a full syntax parser.

Conjunctions, list punctuation, copulas and example/naming phrases have separate
baselines. A shared WordNet noun-type score emphasizes people, groups and
concrete things over abstractions. Plural -s, capitalization, pronouns and modal
verbs provide grammatical adjustments. English subwords are joined in state;
document and sentence boundaries reset the relevant context.
"""
import re
from functools import lru_cache
import wordnet

READS = ()

# Noun kinds are overlapping dictionary categories, not inferred syntax.
NOUN_KINDS = {
    'people': (0.581, {'noun.person'}),
    'living things': (0.256, {'noun.animal', 'noun.plant'}),
    'groups': (0.460, {'noun.group'}),
    'physical things': (0.230, {
        'noun.artifact', 'noun.body', 'noun.substance', 'noun.food', 'noun.object'}),
    'places and shapes': (0.089, {'noun.location', 'noun.shape'}),
    'thought and communication': (-0.092, {'noun.cognition', 'noun.communication'}),
    'abstract things': (-0.431, {
        'noun.act', 'noun.event', 'noun.process', 'noun.feeling',
        'noun.state', 'noun.attribute', 'noun.time'}),
}

# Boundary: baseline, noun-type strength, extra plural-s adjustment.
BOUNDARIES = {
    'other': (0.002, 0.015, 0.000),
    'and': (0.143, 0.467, 0.256),
    'or': (0.185, 0.566, 0.217),
    'comma': (0.044, 0.213, 0.100),
    'paren': (0.081, 0.341, 0.138),
    'colon': (0.044, 0.124, 0.034),
    'be': (0.173, 0.487, -0.023),
    'is': (0.059, 0.262, -0.052),
    'are': (-0.006, 0.351, 0.140),
    'past_be': (-0.052, 0.250, 0.033),
    'as': (0.049, 0.235, 0.054),
    'as_such': (0.240, 0.866, 0.222),
    'as_well': (0.333, -0.000, 0.000),
    'as_comparison': (-0.245, -0.001, 0.000),
    'include': (0.255, 0.467, 0.188),
    'called': (0.223, 0.136, -0.143),
}

# Modal meanings before "be".
MODAL_ADJUSTMENTS = (
    (('can', 'could', 'cannot'), 0.503),
    (('must', 'should', 'shall'), 0.180),
    (('will', "'ll", '’ll'), 0.194),
    (('may',), 0.254),
    (('would', 'might'), -0.132),
    (('to',), 0.016),
)
CAPITALIZED = 0.067
PRONOUN = 0.192
NUMBER = -0.251
AFTER_COMMA = -0.199
NO_WORD = -0.162

CONNECTORS = {'and', 'or', '&', '/or', 'and/or', 'und', 'et', 'ou', 'y', 'и'}
MODALS = {'can', 'could', 'may', 'might', 'will', 'would', 'shall',
          'should', 'must', 'cannot'}
SKIP = MODALS | {'not', 'also', 'still', 'never', 'always', 'only',
                 'even', 'then', 'often'}
PRONOUNS = {'i', 'we', 'you', 'he', 'she', 'it', 'they', 'me', 'us', 'him',
            'her', 'them', 'someone', 'anyone', 'everyone'}


@lru_cache(None)
def noun_score(word):
    categories = wordnet.categories(word.lower()) if word else set()
    score = 0.0
    for weight, classes in NOUN_KINDS.values():
        if categories & classes:
            score += weight
    return score


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', (), '')
    _, fragment, history, last = carry
    word = text.strip().lower()

    role = 'other'
    separate_word = not fragment or (text and text[0].isspace())
    if separate_word:
        if word in CONNECTORS:
            role = 'or' if word in {'or', '/or', 'ou'} else 'and'
        elif word in {'be', 'is', 'are'}:
            role = word
        elif word in {'was', 'were', 'been', 'being'}:
            role = 'past_be'
        elif word == 'as':
            role = 'as'
        elif word in {'include', 'includes', 'included', 'including'}:
            role = 'include'
        elif word == 'called':
            role = 'called'
