        role = 'comma'
    elif text in {' (', '（'}:
        role = 'paren'
    elif text in {':', '：'}:
        role = 'colon'

    words = list(history) + ([fragment] if fragment else [])
    previous = words[-1].lower() if words else ''
    noun = words[-1] if words else ''
    if role == 'as':
        if previous == 'such':
            role = 'as_such'
            noun = words[-2] if len(words) > 1 else ''
        elif previous == 'well':
            role, noun = 'as_well', ''
        elif previous in {'same', 'long', 'far', 'much', 'soon', 'early'}:
            role, noun = 'as_comparison', ''
    if role == 'be':
        noun = next((w for w in reversed(words) if w.lower() not in SKIP), '')
    if noun.lower() in {'that', 'which', 'who'} and len(words) > 1:
        noun = words[-2]

    plural = noun.lower().endswith('s') and not noun.lower().endswith('ss')
    score = noun_score(noun)
    score += CAPITALIZED * (noun.istitle() or (len(noun) > 1 and noun.isupper()))
    score += PRONOUN * (noun.lower() in PRONOUNS)
    score += NUMBER * (bool(last.strip()) and last.strip().isdigit())
    score += AFTER_COMMA * (last.strip() in {',', '，', '、'})
    score += NO_WORD * (not noun)
