            if last.strip().lower() in modals:
                value += adjustment
                break

    # Complete words on separators; keep only a short causal word history.
    for part in re.findall('[A-Za-z]+|[^A-Za-z]+', text):
        if part.isascii() and part.isalpha():
            fragment += part
        else:
            if fragment:
                history = (*history[-4:], fragment)
            fragment = ''
            if any(char in part for char in '\n.!?;'):
                history = ()
    return (document, fragment, history, text), float(value)

