each document gets a small negative value. Everything else is about zero.
"""

CONJUNCTIONS = {" and", " or", "/or", "Or", " und", " y", "和", "或", "及", "以及", "や"}
EXAMPLES = {" including", " include", " includes", " like", " such"}
BRACKETS = {" (", "("}
COPULAS = {" is", " are"}
MODALS = {" can", " could", " may", " must", " will", " should", " might", " would"}
READS = ()


def is_plural(word):
    word = word.strip()
    return len(word) > 3 and word.isalpha() and word.endswith("s")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, -0.23  # first token of a document
    before = prefix.token_strings[-2]
    list_context = is_plural(before) or before == ","
    if token in CONJUNCTIONS:
        value = 0.31 if list_context else 0.21
    elif token == " be":
        value = 0.45 if before in MODALS else 0.2
    elif token in EXAMPLES:
        value = 0.32 if before == "," else 0.08
    elif token in BRACKETS:
        value = 0.32 if is_plural(before) else 0.07
    elif token == " as":
        value = 0.4 if before == " such" else 0.05
    elif token in COPULAS:
        value = 0.07
    elif token == ",":
        value = 0.17 if is_plural(before) else 0.04
    else:
        value = 0.0
    return None, float(value)

