import re

READS = ()
F_OPEN = re.compile(r'''\b[fF][rR]?(["'])''')
FORMAT = re.compile(r'%[-+ #0.\d]*[a-zA-Z]|\{[^{}]*\}')
STREAM = re.compile(r'\b(?:cout|cerr|clog)\b|\bLOG\(')
OUTPUT = re.compile(
    r'\b(?:print|printf|println|log|error|info|warn|debug)\s*\([^()\n]*$',
    re.I,
)


def unescape_quotes(s):
    return re.sub(r'''\\+(["'])''', r'\1', s)


def predict(text, token):
    if not text:
        return -0.2
    if not any(c in token for c in '''"'{+<%.`''') and token.strip().lower() not in (
        'join', 'format', 'str', '=>',
    ):
        return 0.0
    quoted_value = re.search(r'''\\+["']["']$''', text)
    text = unescape_quotes(text)
    plain = unescape_quotes(token)
    s = plain.strip()
    end = text.rstrip(' \t')
    line = text.replace('\\n', '\n').rsplit('\n', 1)[-1]
    closing = end.endswith(('"', "'"))
    if end.endswith('`') and '=' in line and not end.endswith('``'):
        closing = True
