        if s == '%':
            literal = end[:-1].rsplit(end[-1], 1)[-1].rsplit('\n', 1)[-1]
            formatted = re.search(r'%[-+ #0.\d]*[a-zA-Z]', literal)
            return 10.0 if formatted else 0.8
        if s == '+':
            literal = end[:-1].rsplit(end[-1], 1)[-1]
            if '\n' in token:
                return 7.0
            if quoted_value:
                return 12.5
            if literal.endswith(('(', '[', '<', '>')):
                return 10.0
            if len(literal) < 3:
                return 8.5 if literal.endswith(' ') else 6.5
            if literal.endswith((' ', ':', '=')):
                return 12.0
            return 7.5
        if s == '<<':
            return 7.0
        php = '$' in line or 'echo ' in line
        concatenate = s == '.$' or (php and token.startswith(' '))
        return 8.5 if concatenate else 1.0
    if s == 'format' and re.search(r'''["']\.$''', end):
        return 9.0
    if s == 'str' and end.endswith('+'):
        return 4.5
    m = re.search(r'''(["'])\s*(<<|\+|%\(|\.\$)$''', plain)
    if m:
        if line.count(m[1]) % 2 or len(line) < 4:
            return 7.5
        return 0.0
    if s == '<<' and STREAM.search(text[-180:]):
        return 1.2
    if '${' in s:
        if s != '${':
            return 1.7
        if '`' in line or text.replace('```', '').count('`') % 2:
            return 6.5 if token.startswith(' ') else 4.0
        if '"' in line:
            return 3.5
        return 0.1
    if '{' in s and '\n' not in plain:
        before = line + plain.split('{')[0]
        matches = list(F_OPEN.finditer(before))
        if matches:
            m = matches[-1]
            rest = before[m.end():]
            if m[1] not in rest and '\\' not in rest:
                return 6.0 if s == '{' else 2.0
