    m = re.search(r'''(["'])\s*\.$''', plain)
    if m:
        literal = text.rsplit(m[1], 1)[-1] + plain[:m.start()]
        formatted = not plain.startswith('(') and FORMAT.search(literal)
        return 4.5 if formatted else 0.4
    m = re.search(r'''(["'])\s*,''', plain)
    if m:
        literal = text.rsplit(m[1], 1)[-1] + plain[:m.start()]
        if literal.endswith((':', '：')):
            return 4.5
        if FORMAT.search(literal):
            return 5.5 if '{' in plain else 3.8
        if OUTPUT.search(text):
            return 4.0
        return 0.32
    if s in ('":', "':"):
        return 0.18
    if s == '=>':
        return 0.22
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = predict(text, token)
    return (doc, (text + token)[-500:]), value

