"""Splicing a runtime value into a string literal (layers.1.mlp.down_proj, neuron 904).

This component is near zero almost everywhere. It fires at the point in code where a string
literal has just ended, or is being interrupted, and a value is about to be inserted into the
text:

- the operator right after a closed string: `"Moving " + file`, `'Error: %s' % error`,
  `'...'.format(x)`, `'-'.join(xs)`, and `"abc"+x` written without a space;
- the `{` or `${` that opens an interpolation inside a string (f-strings, template literals);
- the comma after a printf-style string with placeholders, `printf("n = %d\\n", n)`, and the
  comma after a label in a print or log call, `console.log('Total:', total)`.

The first token of each document is slightly negative. The sizes are rough averages of the
activations measured in each case.
"""

import re

READS = ()

PLACEHOLDER = re.compile(r"%[-+ #0-9.]*[sdvfxcrjgeoi]|\{[^{}]*\}")  # %s %d {} {name}
PRINT_CALL = re.compile(r"print|log|Print|cout|paste|echo|format|Error|write|printf")
SPLICE = {" +": 9.0, " %": 12.0, " <<": 6.0, "format": 3.0, "join": 2.4, ".join": 2.4}
OPENERS = {" {", "{"}  # interpolation opened inside a string
TEMPLATE_OPENERS = {" ${", "${"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    new_document = len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if carry is None or new_document:
        quote, text, prev_closed, line = None, "", False, ""
    else:
        quote, text, prev_closed, line = carry

    value = 0.0
    if prev_closed and token in SPLICE:
        value = SPLICE[token]
    elif quote is not None and token in OPENERS:
        value = 3.0
    elif token in TEMPLATE_OPENERS:
        value = 4.0
    printy = bool(PRINT_CALL.search(line))

    closed = None  # the text of a string literal this token closes
    for ch in token:
        if quote is None:
            if ch in "\"'":
                quote, text = ch, ""
        elif ch == quote:
            closed, quote, text = text, None, ""
        else:
            text += ch
    if quote is not None and "\n" in token:
        quote, text = None, ""  # ordinary string literals do not span lines

    if value == 0.0 and closed is not None:
        if PLACEHOLDER.search(closed) and "," in token:
