"""A heuristic for boundaries of mathematical notation and dollar expressions.

Opening dollars tend positive; closing dollars and LaTeX parentheses tend
negative, especially after short spans. Whitespace and attached punctuation
help distinguish them. A few conventional dollar constructions (subscripts,
R-style field access, revision keywords and JSON schema keys) are separate.
The state is just delimiter distances, the last delimiter's role, and a short
text suffix. It resets at each document; it is not a mathematical parser.
"""
import math
import re

READS = ()


def close_dollar(age, double=False):
    strength = math.sqrt(2.0 / max(1, age))
    return -4.24 * strength if double else 0.59 - 3.63 * strength


def predict(s, previous, tail, dollar_age, paren_age, position, opened):
    if '$' not in s:
        if previous.endswith('$'):
            if s == 'Id':                 # RCS/CVS revision keyword $Id
                return -9.8, opened
            if s == 'schema' and tail.endswith('"$'):
                return -8.7, opened      # JSON's "$schema" field
        if s.startswith('\\)'):
            return -3.05 * math.sqrt(4.0 / max(1, paren_age)), opened
        if s.startswith(')') and previous.endswith('\\'):
            value = 1.09 - 5.22 * math.sqrt(4.0 / max(1, paren_age))
            return value, opened
        if s.startswith(']') and previous.endswith('\\'):
            return 0.78, opened
        if s == '`' and previous and not previous[-1].isspace():
            return -0.2, opened
        return 0.0, opened

    left, right = s.split('$', 1)
    if left.endswith('\\'):
        return 0.45, opened
    if position == 0 and s in ('$', ' $'):
        return (-2.44 if s == '$' else -1.8), False
    if left == '{':
        latex_command = re.search(r'\\[A-Za-z]+$', tail)
        return (8.2, True) if latex_command else (0.5, None)
    if left.endswith('['):
        return (7.0, True) if tail.endswith('\\item') else (0.3, None)
    if right.startswith('_'):
        if not left and previous[-1:].isalnum():
            extra = 2.5 if previous.startswith(('{', '(')) else 0.0
            return 4.3 + extra, True
        return 0.5, None
    if right[:1].isalpha():
        field_access = not left and previous[-1:].isalnum()
        return (4.5 if field_access else 0.6), None
    if right.startswith('.'):
        return -0.42, False
    if right.startswith(','):
        return -0.87, False
    if '\n' in right:
        return -0.42, False
    if left and left[-1] in '}])':
        return -0.85 - 1.84 * math.sqrt(2.0 / max(1, dollar_age)), False
    if right.startswith('\\'):
        return (0.8 if left.isspace() else 1.55), True

    # A dollar following a completed formula may start a unit's exponent
    # ("$9$ cm$^2$") or a second formula after a dash.
    if s == '$' and opened is False:
        if re.search(r'(?:\b(?:mm|cm|km|kg|m|s)|[–—])$', tail):
            return 2.8, True
    if s == '$' and not opened and re.search(r'\s[0-9.]+$', tail):
        return 2.55, False              # a currency amount written "10$"
    if left.isspace() and right in ('', '$'):
        math_ending = (previous.strip().isalnum() and
                       (not previous[:1].isspace() or len(previous.strip()) == 1))
        math_ending = math_ending or '\\%' in previous
        if opened and dollar_age <= 32 and math_ending:
            return close_dollar(dollar_age, right == '$'), False
        return 0.48, True
    if right not in ('', '$'):
        return 0.0, opened
    if left:
        if left[-1] in '+-*' and opened:
            return close_dollar(dollar_age), False
        if left[-1] in '(=:-/':
            return 1.18, True
        if left[-1] == '.':
            return 0.77, True
        return 0.0, opened
    if previous[-1:].isspace() or previous.endswith('\\n'):
        return 1.23, True
    if previous[-1:] in '({[=:':
        return 1.18, True
    return close_dollar(dollar_age, s == '$$'), False


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        carry = (document, '', '', 1000, 1000, 0, None)
    _, previous, tail, dollar_age, paren_age, position, opened = carry
    token = prefix.token_strings[-1]
    value, opened = predict(token, previous, tail, dollar_age,
                            paren_age, position, opened)
    dollar_age = 1 if '$' in token else dollar_age + 1
    begins_parenthesis = ('\\(' in token or
                          token.startswith('(') and previous.endswith('\\'))
    paren_age = 1 if begins_parenthesis else paren_age + 1
    carry = (document, token, (tail + token)[-32:], dollar_age,
             paren_age, position + 1, opened)
    return carry, float(value)

