"""Dollar-sign detector for LaTeX math (layers.1 mlp down_proj, unit 910).

This unit writes a large signed signal onto the "$" family of tokens and is nearly silent
on everything else. What it writes depends on what the dollar sign is doing:

- A "$", "$$" or "}$" right after a word, digit or closing brace, inside LaTeX math
  ("$x$", "$\\alpha$", "$10^{-3}$"), is strongly negative, about -2.2. So is a closing
  "\\)" or a ")" after "\\" (about -3.5), and a ")$" (about -1.5).
- A "$" after a digit in text with no LaTeX yet is a currency sign ("1$", "R$1250"):
  positive, about +3.
- A "$" glued to an opening bracket, subscript or equals sign ("{$", "[$", "$_", "=$",
  "$\\") starts math inside a table, list or formula: positive, about +2 to +5.
- A space-dollar " $" that opens inline math in prose is slightly positive, about +0.35.
- The RCS keyword "$Id" in a source header is strongly negative, about -9.

Everything else predicts 0. "Inside math" is tracked by counting "$" tokens in the
document (an odd count means a span is open); "LaTeX so far" means a backslash has
appeared in the document. The state resets at each document boundary.
"""
READS = ()

CLOSERS = ("$", "$$", "}$")
OPENERS = {"{$": 5.0, "[$": 5.0, "$_": 4.5, "$p": 5.0, "$v": 5.0, "=$": 2.0, "$\\": 1.4}

def _word_end(s):
    return s[-1:].isalnum() or s[-1:] in "}])"

def step(carry, prefix, upstream):
    toks = prefix.token_strings
    s = toks[-1]
    prev = toks[-2] if len(toks) > 1 else " "
    first = len(toks) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]
    inside, latex = (False, False) if first or carry is None else carry
    value = 0.0
    if s in CLOSERS:
        if _word_end(prev):
            if inside or latex:
                value = -2.2
            elif prev[-1:].isdigit():
                value = 3.0
        elif prev[-1:].isspace():
            value = 1.0
    elif s == ")$":
        value = -1.5 if (inside or latex) else 0.0
    elif s in OPENERS:
        value = OPENERS[s]
    elif s in (" $", " $\\"):
        value = 0.35
    elif s == " $$":
        value = 0.7
    elif s == ")" and prev in (" \\", "\\"):
        value = -3.5
    elif s == "\\)":
        value = -3.5
    elif s == "Id" and prev in ("$", " $"):
        value = -9.0
    if "$" in s:
        inside = not inside
    if "\\" in s:
        latex = True
    return (inside, latex), value

