import re

READS = ()
_NUMBER = re.compile(r'[0-9][0-9.,]*$')
_VERSION_LABEL = re.compile(r'\b(?:version|python|usb)\s*[:=]?\s*$', re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = 0.0
    if token.strip().lower() == 'wait':
        value = 0.59 if token[:1].isspace() else 0.52
    elif token.strip().lower() in ('waits', 'waited', 'waiting'):
        value = 0.35
    elif len(token) >= 2 and not token.strip('·'):
        value = 0.91
    elif token.startswith(',') and text.lower().endswith('wait'):
        value = 0.20
    elif len(token) == 1 and token in '0123456789':
        match = _NUMBER.search(text)
        number = match.group() if match else ''
        before = text[:match.start()] if match else text
        if number and ',' not in number:
            if '.' in number:
                integer, fraction = number.rsplit('.', 1)
                if not fraction:
                    if token == '0':
                        value = (0.55 if integer == '0' else
                                 1.0 if integer == '1' else 0.30)
                    else:
                        value = 0.05 if integer == '0' else 0.12
                elif not fraction.strip('0') and token == '0':
                    value = 0.89 if integer == '0' else 0.25
                elif token == '0':
                    value = -0.035
