                version = (before.endswith(('/', '__')) or
                           before[-1:].isascii() and before[-1:].isalpha() or
                           _VERSION_LABEL.search(before) is not None)
                if version:
                    if not fraction:
                        value = 1.0 if token == '0' else 0.60
                    elif len(fraction) == 1:
                        value = 0.25
                    else:
                        value = 0.04
            elif not number.strip('0') and token == '0':
                value = 0.80
                if before.endswith('['):
                    value = 1.25
                elif before.endswith(':'):
                    value = 0.45
                if len(number) >= 3:
                    value = 1.30
        elif not number and token == '0':
            if not text:
                value = 0.465
            elif before[-1:].isascii() and before[-1:].isalpha():
                value = 0.40
            elif before.endswith('-'):
                value = 0.14
    return (doc, (text + token)[-80:]), value

"""Written two, strongest as a name's suffix or a mathematical index.

Numbers embedded in decimal strings are weak, especially after 1 or 2.
Latin names, acronyms, subscripts and Roman II are stronger. Name length
and ordinary English word frequency soften the name-suffix response.
A few other written-two forms and the homophone 'to' in names are included.
"""
import calendar
import re
from wordfreq import zipf_frequency

READS = ()
MONTHS = {w.lower() for w in (*calendar.month_name, *calendar.month_abbr) if w}


def two_value(text, position):
    if position == 0 or text and not text.strip('2'):
        return -0.64
    last = text[-1:]
    if last in '0123456789' and last:
        if last == '1':
            return -0.07
        if last == '2':
            return -0.12
        return 0.12
    if re.search(r'\\x[0-9a-fA-F]*\Z', text):
        return 0.08
    match = re.search(r'([A-Za-z]+)([^A-Za-z]*)\Z', text)
    word, gap = match.groups() if match else ('', '')
    if word and not gap:
        value = 1.22 - 0.04 * min(len(word), 12)
        value -= 0.05 * zipf_frequency(word, 'en')
        value += 0.23 * word.isupper() - 0.08 * (len(word) == 1)
        return value
    if text.endswith(('_', '_{')):
        return 0.58
    if word and gap in ('-', '/', '~'):
        if word.isupper() and len(word) > 1:
            return 1.05
        return 0.65 if gap == '-' else 0.35
    if last.isspace():
        value = 0.03
        if word and gap == ' ':
            value += 0.31 - 0.03 * zipf_frequency(word, 'en')
            value += 0.27 * word.isupper() + 0.11 * (len(word) == 1)
            value -= 0.19 * (word.lower() in MONTHS)
        return value
    return 0.12 if last == '^' else 0.06


