    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        text, position = '', 0
    else:
        _, text, position = carry
    token = prefix.token_strings[-1]
    stripped = token.strip()
    value = 0.0
    if token == '2':
        value = two_value(text, position)
    elif stripped in ('II', '-II', '(II'):
        value = -0.05 if text.endswith('I') else 0.74
    elif stripped in ('ii', '(ii'):
        value = 0.25 if text[-1:].isalpha() else 0.52
    elif stripped == '₂':
        value = 0.60 if position else -0.27
    elif stripped == '²':
        value = 0.105
    elif stripped.lower() == 'two':
        value = (0.10 if token.startswith(' ') else 0.18) if position else -0.17
    elif stripped.lower() == 'dioxide':
        value = 1.0
    elif stripped.startswith('第二'):
