def vowel_pairs(text):
    return {text[i:i+2] for i in range(len(text)-1)
            if text[i] in VOWELS and text[i+1] in VOWELS}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, before = carry[1:] if carry and carry[0] == doc else ('', '')
    token = prefix.token_strings[-1]
    text = spelling(token)
    continuing = bool(previous and text and previous[-1].isalpha()
                      and text[0].isalpha())
    value = -.01 - .015*continuing + .02*(not token.isascii())
    length = min(len(text.strip()), 12)
    for pair in vowel_pairs(text):
        value += INTERNAL.get(pair, .13) - .017*length
    if continuing:
        pair = text[:2]
        if len(pair) == 2 and all(c in VOWELS for c in pair):
            default = 0. if pair[0] == 'y' else .15
            value += INITIAL.get(pair, default) - .01*length
        pair = previous[-1] + text[0]
        if all(c in VOWELS for c in pair):
            value += JOIN.get(pair, .15)
        value += PERSIST.get(previous[-2:], 0.)
        if before and all(c in VOWELS for c in previous):
            pair = before[-1] + previous[0]
            value += DELAYED.get(pair, 0.)
    return (doc, text, previous), float(value)

programs.haiku:
"""Layer-1 MLP down_proj component 916: a vowel-pair word-fragment detector.

What it responds to, in plain terms:
  * the first token of each document (a fresh context): a moderate positive value;
  * tokens whose spelling contains a vowel pair (ai, ay, au, oi, oa, ou, ea, oo ...);
  * above all the "ai" family ("ai", "ail", "air", "aid", "aim", "ain", "main"), most
    strongly when the token is a piece inside a word (no leading space);
  * word fragments made mostly of vowels, and partial UTF-8 byte pieces (CJK, Cyrillic,
    Greek letters split across tokens);
  * very short unspaced fragments, slightly.
Its output promotes word-ending continuations, so it reads as "this is a vowel-heavy piece
of a split word". The prediction is a fixed weighted sum of these cues, with no learned table.
"""

READS = ()

VOWELS = set("aeiouyàáâãäåèéêëìíîïòóôõöùúûüÿæœ" "αεηιουωίΐ" "аеёиоуыэюя" "あいうえおアイウエオ")
PAIRS = ("ai", "ay", "au", "oi", "oy", "oa", "ou", "ea", "ei", "ui", "ey", "oe", "oo")


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids
    value = 0.0
    if len(doc) == 1 or doc[-1] != doc[-2]:
        value += 0.21
    text = token.strip().lower()
    unspaced = not token.startswith(" ") and len(text) > 0
    letters = [ch for ch in text if ch.isalpha()]
    if any(p in text for p in PAIRS):
        value += 0.13
    if "ai" in text:
        value += 0.50 if unspaced else 0.12
    if unspaced and letters:
        value += 0.09 * sum(ch in VOWELS for ch in letters) / len(letters)
    if "�" in token:
        value += 0.11
    if unspaced and 0 < len(letters) <= 3:
        value += 0.03
    return carry, float(value)

"""Clause-joint detector for layers.1.mlp.down_proj:917.

The component reads the MLP's hidden state at each token and writes a small signal
into the residual stream. Its sign depends mostly on the punctuation just before the
token and on what kind of word the token is (values are rounded cell means on
training text):

* After a semicolon, a list conjunction (and, or, nor, but) is strongly negative
  (-1.3). A clause opener (the, this, for, however, in) is positive (+0.55).
  A bare space or other token after a semicolon is slightly negative.
* After a comma, a German or Russian particle that opens a continuation (doch,
  auch, nur, dann, так, в) is strongly positive (+0.8). An English function word
  (in, for, that, the) is mildly positive (+0.15). "or" is mildly negative (-0.4),
  and "and" or "but" about zero.
* List and format markers (、 • \\ and ",\n\n") are mildly negative (-0.3), anywhere.
* After a period, a conjunction is slightly negative (-0.1).

Everything else is 0. It explains about 9% of the activation variance; it gets the
sign right on the strongest events (semicolon conjunctions, German particles after a
comma) but leaves out most of the within-context variation.
"""

READS = ()

SEMI = {";", ";\n"}
COMMA = {",", ",\n", ",\n\n", "，", "、", '",', "),"}
PERIOD = {".", "。"}
CONJ = {"and", "or", "nor", "but", "/or"}
FUNC = {"in", "for", "the", "that", "this", "also", "however", "only", "then", "if", "as",
        "to", "so", "a", "it", "we", "which", "with", "at", "of", "from", "by", "on", "while", "when"}
PARTICLES = {"doch", "auch", "nur", "dann", "also", "und", "aber", "oder", "bei", "von", "aus",
             "mit", "für", "так", "тогда", "ведь", "и", "в", "на", "для", "при", "этом", "также"}


MARKERS = {"、", "•", "\\", ",\n\n"}


def step(carry, prefix, upstream):
    if len(prefix) < 2 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    prev = prefix.token_strings[-2]
    raw = prefix.token_strings[-1]
    cur = raw.strip()
    if raw in MARKERS:
        return carry, -0.3
    if prev in COMMA and cur == "or":
        return carry, -0.4
    if prev in SEMI:
        if cur in CONJ:
            return carry, -1.3
        if cur in FUNC:
            return carry, 0.55
        if cur == "":
            return carry, -0.15
        return carry, -0.05
    if prev in COMMA:
        if cur.lower() in PARTICLES:
            return carry, 0.8
        if cur in FUNC:
            return carry, 0.15
        if cur in CONJ:
            return carry, -0.08
        return carry, 0.0
    if prev in PERIOD and cur in CONJ:
        return carry, -0.1
    return carry, 0.0

programs.sol:
"""Approximate the component's document-initial pulse.

Large training activations occurred at the first token, especially programming
scalar types. These rules estimate that pulse from lexical classes and visible
formatting. They deliberately omit its fine-grained token-specific variation
and approximate all interior activations by zero.
"""
import re
import unicodedata

READS = ()
INTEGER_TYPES = {'int', 'uint'}
LEXICAL_STRENGTHS = (
    (INTEGER_TYPES, 56.0),
    ({'float', 'double'}, 33.0),
    ({'long', 'short', 'byte', 'unsigned'}, 25.0),
    ({'char', 'str', 'string'}, 27.0),
    ({'list', 'vector', 'vec'}, 24.0),
    ({'dict', 'tuple', 'set', 'array'}, 12.0),
    ({'range', 'len', 'sum', 'min', 'max', 'abs', 'pow', 'round'}, 12.0),
    ({'day', 'week', 'month', 'year'}, 12.0),
)
COPULAS = {'am', 'is', 'are', 'was', 'were', 'be', 'been', 'being'}
MODALS = {'will', 'would', 'shall', 'should', 'can', 'could', 'may', 'might', 'must'}


def start_value(s):
    if s.startswith('<|'):
        return 0.15
    if s == ' ':
        return 4.33
    if s.isspace():
        return 3.2 if s == '\t' else 0.5
    bare = s.strip()
    if not bare:
        return 0.0
    if bare.isnumeric():
        return -0.35

    # Allow indentation and code delimiters before these names.
    word = bare.lstrip('._(<=:').strip()
    lower = word.lower()
    for words, amount in LEXICAL_STRENGTHS:
        if lower not in words:
            continue
        if word != lower:
            amount *= 0.25 if lower in INTEGER_TYPES else 0.55
        if s.startswith(' '):
            amount *= 0.45
        elif s.startswith('\t'):
            amount *= 0.68
        elif word != bare:
            amount *= 0.4
        return amount

    spaced = s.startswith(' ')
    if bare in {'var', 'let'}:
        return 5.5 if spaced else 16.0
    if bare in {'func', 'fn', 'function'}:
        return 3.0 if spaced else 14.0
    if bare in {'const', 'static', 'class', 'struct', 'def', 'return'}:
        return 2.0 if spaced else 4.5
    if bare in {'import', 'package', 'using', 'include'}:
        return -0.5
    if lower == 'be':
        return 3.5 if spaced else (4.2 if bare[0].isupper() else 19.0)
    if lower == 'will':
        return 2.5 if spaced else 15.0
    if lower in COPULAS:
        return 1.4 if spaced else (0.0 if bare[0].isupper() else 6.0)
    if lower in MODALS:
        return 0.9 if spaced else 7.0
    if lower in {'no', 'not'}:
        return 1.5 if spaced else (3.5 if bare[0].isupper() else 10.0)

    if re.match(r'^\\x[0-9a-fA-F]*$', bare):
        return 23.0
    if bare.startswith('\\"'):
        return 8.0
    if any(unicodedata.category(c) == 'Sc' for c in bare):
        return 8.0 if '$' in bare else 17.0
    if bare.startswith('&#'):
        return 20.0
    if not any(c.isalnum() for c in bare):
        if s == s.rstrip() and bare in {'(', '[', '{'}:
            return 4.5
        if bare in {')', ']', '}'}:
            return -1.25
        if bare == '+':
            return 3.0 if spaced else 6.6
        if bare in {'-', '*', '^', '@', '//'}:
            return 2.4
        if bare == '#':
            return 8.0 if spaced else 0.8
        if bare in {'.', ',', ':', ';'}:
            return -1.5 if spaced else 1.3
        return 1.5
    if not bare.isascii():
        return 0.5
    if spaced:
        return 0.4
    if len(bare) == 1:
        return -0.2 if bare.isupper() else 0.8
    return 0.5 if bare[0].isupper() else 2.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    first = carry is None or carry != document
    value = start_value(prefix.token_strings[-1]) if first else 0.0
    return document, value

programs.haiku:
"""layers.1.mlp.down_proj:918 as a first-token-of-document detector.

In Qwen3-1.7B this component is almost silent everywhere except on the first token of a
document (the token right after <|endoftext|>, or the first token of a row). There its
activation depends only on which token it is, because the token attends to nothing but
itself. The program therefore predicts a value at document starts only, chosen by the kind
of token:

  * programming scalar/container type names (int, uint, float, double, string, char, long,
    vec, ptr, ...): large, about 24;
  * a lowercase word with no leading space (a word piece or identifier, e.g. "be", "user"):
    about 2;
  * whitespace-only or ASCII punctuation tokens: about 1 to 2;
  * digits: slightly negative;
  * anything else (words with a leading space, capitalised words, non-ASCII text): about 0.6.

Every other position predicts 0.
"""

import re

TYPE_NAMES = {
    "int", "uint", "float", "double", "long", "short", "char", "unsigned", "byte",
    "string", "str", "vec", "ivec", "ptr", "array", "list", "dict", "tuple", "utf",
    "wchar", "bool", "size_t", "uintptr", "intptr",
}

READS = ()


def _value(token: str) -> float:
    word = token.strip()
    if word.lower() in TYPE_NAMES:
        return 24.0
    if word == "":
        return 2.0
    if re.fullmatch(r"[a-z]+", word) and not token.startswith(" "):
        return 2.0
    if re.fullmatch(r"[^A-Za-z0-9\s]+", word):
        return 1.3
    if re.fullmatch(r"[0-9]+", word):
        return -0.4
    return 0.6


def step(carry, prefix, upstream):
    t = prefix.position
    starts_document = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if not starts_document:
        return carry, 0.0
    return carry, _value(prefix.token_strings[-1])

programs.sol:
"""Detect English denial spellings, with their token-boundary effects.

Deny/denial words give a large negative response, especially when split
between tokens.  The name Denis shares the spelling and also responds.
Cross-token Japanese/Korean de-ni syllables, Chinese 'deny', and the name Danny in Chinese
are parallels.  'Of' immediately after 'denial' retains a weaker response.
Other uses of 'den' (garden, density, denoted, etc.) are not denial.
Weaker responses to other d-related word fragments are left at zero.
The isolated den fragment is only weakly negative, more so in capitals.
"""
import codecs
import re
import regex
from anyascii import anyascii

READS = ()
DENIAL = re.compile(r'den(?:y|i(?:al|e[ds]|ers?))')
DENIS = re.compile(r'(?<![a-z])denis$')


def word_start(text, index):
    if index == 0:
        return True
    previous = text[index - 1]
    # An uppercase D can start a CamelCase word such as AccessDenied.
    return (not previous.isascii() or not previous.isalpha()
            or (text[index] == 'D' and previous.islower()))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, pending = '', b''
    else:
        _, tail, pending = carry
    decoder = codecs.getincrementaldecoder('utf-8')('ignore')
    decoder.setstate((pending, 0))
    token = decoder.decode(prefix.token_bytes[-1])
    pending = decoder.getstate()[0]
    joined = tail + token
    lower = joined.lower()
    boundary = len(tail)
    value = 0.0
    matches = [m for m in DENIAL.finditer(lower)
               if m.end() > boundary and word_start(joined, m.start())]
    if matches:
        match = matches[-1]
        word = match.group()
        value = -11.0 if word == 'denial' else -10.5
        if word == 'denied':
            value = -9.1
        if match.start() < boundary:
            value = -13.0
        if word.startswith('denier'):
            value = -8.2
    elif (match := DENIS.search(lower)) is not None:
        if match.end() > boundary:
            value = -9.5 if match.start() < boundary else -5.4
    elif token.lower() == ' of' and tail.lower().endswith('denial'):
        value = -4.0
    elif token.strip() == 'DEN':
        value = -1.9
    elif token.strip() == 'Den':
        value = -0.9
    elif token.strip() == 'den':
        value = -0.1
    if value == 0.0 and token:
        # A cross-token de-ni sound, notably in Japanese 'denim'.
        syllabic = r'\p{scx=Katakana}|\p{Hangul}'
        if (regex.fullmatch(syllabic, tail[-1:])
                and not regex.fullmatch(syllabic, tail[-2:-1])):
            if anyascii(tail[-1:]).lower() == 'de':
                if anyascii(token).lower().startswith('ni'):
                    value = -7.8
        if re.search(r'否[认認]$', joined):
            value = -4.5
        if joined.endswith('丹尼'):
            value = -8.0
    return (doc, joined[-24:], pending), value

"""Approximate a preference for plain-text mathematical notation.

Division signs, radicals, powers, and groups following operators are positive;
ordinary prose and file-path slashes are mostly quiet. Backslash-prefixed LaTeX
is distinguished from unescaped mathematical names. Also recognize Mathematica
box notation and the colon in a document's initial 'Title:' heading.
Only a short recent text buffer is retained, reset at document boundaries.
"""
import re

READS = ()
GREEK = set(('alpha beta gamma delta epsilon zeta eta theta iota kappa lambda mu '
             'nu xi omicron pi rho sigma tau upsilon phi chi psi omega').split())


def predict(s, prev, history):
    t, p = s.strip(), prev.strip()
    h = history.rstrip()
    recent = h[-80:]
    escaped = h.endswith('\\')
    equation = float('=' in recent)
    math = float(bool(re.search(
        r'[=²³√^]|\b(?:sqrt|pi|sin|cos|frac|sum)\b', recent)))
    digit = float(bool(p) and p[-1].isdigit())
    variable = float(bool(re.fullmatch('[a-zA-Z]', p)))
    close = float(p.endswith((')', ']', '}')))
    opening = float(p.endswith(('(', '[')))
    division = float(p.endswith('/'))
    equals = float(p.endswith('='))
    add = float(p in ('+', '-', '−', '±'))
    pi = float(bool(re.search(r'(?:\bpi|π)\W*$', h)))

    if t == ':' and h == 'Title':
        return 10.277
    if t.lstrip('([') == 'sqrt':
        if escaped:
            return 0.70
        return 2.05 + .4*equals + .55*division + .3*variable - .2*add
    if t == '√':
        return 1.10
    name = t.lstrip('([')
    if name == 'pi':
        if escaped:
            return .12
        return .15 + .6*digit + .3*equals + .2*opening + .75*math + .2*equation
    if name in GREEK:
        if escaped:
            return .12
        return .1 + .2*digit + .15*opening + .2*math + .3*(name in ('theta', 'phi'))

    if '/' in t and re.fullmatch(r'[()\[\]/]+', t) and t.count('/') == 1:
        if t != '/':
            return (.47 + .27*digit + .28*variable + .34*math
                    + .32*('(' in t) + .35*t.startswith((')', ']'))
                    - .41*s.startswith(' '))
        path = bool(re.search(r'https?://|/\w{3,}/|\.\w{2,4}/', recent))
        if path:
            return .04
        return (.06 + .27*digit + .27*close + .1*variable + .86*pi
                + .27*equation + .39*math)
    if t == '/d':
        return 2.3 if re.search(r'\bd$', h) else .07 + .65*math
    if re.fullmatch(r'\(+', t):
        root = p in ('sqrt', '√')
        return (.36*equals + .8*division + .24*add + .38*opening
                + 1.4*root + .11*math - .13*variable)
    if re.fullmatch(r'\[+', t):
        return (.08*equals + .5*division + .16*add + .08*math
                + .4*(p == 'Box'))
    if re.fullmatch(r'\)+', t):
        return -.04 + .17*s.startswith(' ') + .06*math
    if '^' in t and re.fullmatch(r'[()^{}]+', t):
        return (.11*variable + .39*pi + .1*equation
                + .46*('(' in t)
                + .7*(p in GREEK and not re.search(r'\\[A-Za-z]+$', h)))
    if t in ('*', '*(', ')*', ')*('):
        return .18*digit + .11*close + .27*('(' in t) + .2*t.startswith(')')
    if t in ('squared', 'cubed', 'cub'):
        return .4 + .7*(variable or p in GREEK) + .4*digit + 1.2*pi + .6*math
    if t in ('frac', 'dfrac', 'tfrac'):
        return .25
    if t == 'over':
        if p in ('sum', 'squared', 'negative', 'infinity', 'integral'):
            return 3.2
        if p == 'root':
            return 4.5
        return -.04 + .25*digit + .28*variable + .52*math + .1*equation
    if t == 'of':
        if re.search(r'\b(?:square|cube|nth) root$', h):
            return 3.2
        if p in ('integral', 'trace', 'infinity', 'negative'):
            return 1.8
        return 0.0
    if t == 'by' and p == 'divided':
        return 1.2
    if t == 'from' and re.search(r'\bsum(?: over [a-z])?$', h, re.I):
        return 2.7
    if t in ('divided', 'times'):
        return .1 + .55*digit + .2*math
    if t in ('approaches', 'approaching'):
        return .1 + 1.5*variable
    if t in ('degree', 'degrees'):
        return (-.08 + (1.0 if t == 'degree' else .45)*digit)

    if t in ('subscript', 'superscript'):
        return 9.0 if p == 'start' else 6.0 if p == 'end' else .2
    if t == '_{':
        return 2.3 if p.lower() in ('sum', 'lim', 'integral') else -.15*variable
    if t == '_':
        return -.1
    if t.isdigit() and p in ('sqrt', '√'):
        return 1.7
    if t == 'as' and p == 'limit':
        return 2.5
    if t == 'ed' and p == 'cub':
        return 2.0 if math or re.search(r'\b[a-z] cub$', h) else 0.0
    if t == 'qrt' and h.endswith('s'):
        return 2.5
    if t == 'overs' and p == 'Under':
        return 2.5
    if t == 'Box':
        if re.search(r'(?:Super|Sub|Under|Over).*script$', h):
            return 3.2
        if p == 'Row':
            return 2.5 if prev.startswith(' ') else 1.5
        if h.endswith(('Fraction', 'Sqrt')):
            return 1.5
        return 0.0
    if t in ('cript', 'script') and re.search(r'(?:Supers|Subs|Underovers)$', h):
        return 4.3
    if t in ('rightarrow', 'leftarrow', 'leftrightarrow'):
        return 4.5 if re.search(r'(?<!\\)over$', h) else .1
    if t == '{':
        if p in ('begin', 'end'):
            raw = not re.search(r'\\(?:begin|end)$', h)
            return (8.0 if p == 'begin' else 5.0) if raw else .55
        if re.search(r'(?<!\\)overrightarrow$', h):
            return 3.0
        if h.endswith(('mathbf', 'mathbb')):
            return -.6
        if h.endswith(('mathrm', 'mathcal')):
            return -.25
        return -.06
    if t == '\\':
        return -.4*variable - .2*digit + .08*s.startswith(' ')
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, prev, history = carry
    s = prefix.token_strings[-1]
    value = predict(s, prev, history)
    return (doc, s, (history + s)[-160:]), float(value)

programs.haiku:
"""Layer 1 MLP output unit 921: a maths-operator detector.

In plain terms, this component fires on the symbols that open or divide a
formula in worked mathematics written in prose:

- "sqrt" is the strongest trigger, and "pi", "phi" and "squared" are also high.
  "sqrt" is weaker (about half) inside LaTeX ("$", "\\" on the line).
- A division slash that is part of a fraction or ratio ("1/2", "16/5",
  "pi/2", "(x)/(1-x)") is high when the line is an equation (it has an "=").
  A slash in a date, path or ID ("10/21", "src/lib") is about zero.
- An opening bracket right after "sqrt", or after "=" in an equation, is
  moderately high.
- Subscript and superscript markup (".sub", ".sup", as in chemical formulas)
  is moderately high.
- LaTeX backslashes and "\\rightarrow" are slightly negative.

Everything else predicts 0. The program reads only the current token, the
previous token and the current line of the same document, so it is causal.
"""

READS = ()

CONSTANTS = {"sqrt": 1.4, "pi": 1.0, "phi": 1.0, "squared": 1.2}
SLASH_PAIRS = {"/(", ")/(", ")/"}
SLASHES = {"/", " /"}
SUBSCRIPTS = {".sub", ".sup"}
LATEX_NEGATIVE = {"\\", "rightarrow"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    docs = prefix.document_ids
    # The current line, counting back only within the current document.
    lo = max(0, len(docs) - 26)
    while lo < len(docs) - 1 and docs[lo] != docs[-1]:
        lo += 1
    line = "".join(tokens[lo:-1]).split("\n")[-1]
    in_equation = "=" in line
    tok = tokens[-1].strip()
    prev = tokens[-2].strip() if len(tokens) > 1 and docs[-2] == docs[-1] else ""

    if tok in CONSTANTS:
        return None, CONSTANTS[tok] * (0.5 if "$" in line or "\\" in line else 1.0)
    if tokens[-1] in SLASH_PAIRS:
        return None, 1.4
    if tokens[-1] in SLASHES:
        value = 0.6 if in_equation else 0.1
        return None, value + (0.2 if prev.isdigit() else 0.0)
    if tokens[-1] in ("(", " ("):
        if prev == "sqrt" or (in_equation and prev in ("=", "sqrt", "pi", "phi")):
            return None, 0.8
        return None, 0.0
    if tokens[-1] in SUBSCRIPTS:
        return None, 0.8
    if tokens[-1] in LATEX_NEGATIVE:
        return None, -0.3
    return None, 0.0

programs.sol:
"""A lexical-boundary approximation, chiefly for Mandarin grammatical words.

It gives larger positive values when a token completes a connective, modal,
question, or deictic expression. Whole-token words have separate, smaller
responses. Traditional variants of grammatical endings are distinguished.
Negative rules cover kinship/intimacy compounds and a few mathematical
quantities. Other rules cover Vietnamese phrases and document openings.
Unmodelled token-specific background values are left at zero.
"""
from functools import lru_cache
import opencc
import regex
import cedict

READS = ()
_SIMPLIFY = opencc.OpenCC('t2s')
_HAN = regex.compile(r'\p{Script=Han}')

# Each entry is (meaning, expressions, activation).
WHOLE = (
    ('ability', {'能够'}, .82),
    ('past aspect', {'已经', '曾经'}, .51),
    ('addition', {'并且', '而且'}, .40),
)
COMPLETIONS = (
    ('ability', {'能够'}, 3.5),
    ('obligation', {'应当'}, 2.1),
    ('coordination', {'并且', '或者'}, 2.75),
    ('modal question', {'可否', '能否'}, 1.8),
    ('logical link', {'所以', '可以', '再者', '何以'}, 1.0),
    ('question', {'如何', '为何', '怎么', '怎麽', '难道'}, .9),
    ('deictic', {a+b for a in '这那怎' for b in '么麽样里种'}, 1.0),
    ('time', {'当初', '当时', '终于', '依旧'}, 1.1),
    ('reference', {'对于'}, .85),
    ('equality', {'等于'}, 1.5),
    ('concession or certainty', {'虽然', '当然'}, 1.95),
    ('unexpectedness', {'竟然', '居然', '偶然'}, 1.0),
    ('naturally', {'自然'}, .6),
    ('knowing, saying, seeing', {'知道', '说道', '看来', '看作', '看成', '看到'}, 1.0),
    ('directional complement', {'出来', '到达'}, 1.3),
)
PROSE_OPENERS = set('''The A An This That These Those I We You He She It They
There Our My Your His Her Its Their In On At By For From With Without As If'''.split())
DECLARATIONS = set('''class function struct let fn def package import require
interface enum const var pub using namespace template'''.split())

@lru_cache(maxsize=8192)
def simplify(s):
    return _SIMPLIFY.convert(''.join(s.split()))

@lru_cache(maxsize=8192)
def known_word(s):
    return bool(cedict.glosses(s))


def predict(previous, current, position):
    if position == 0:
        if current == 'Title':
            return .56
        if current in PROSE_OPENERS:
            return .36
        if current in {'class', 'function', 'struct', 'fn', 'let'}:
            return -1.3
        if current in DECLARATIONS:
            return -.25
        if current.startswith(('/*', '//')):
            return -.50
    if position == 1 and previous.strip() == 'Title' and current == ':':
        return -3.89
    if current.strip() == 'thể' and previous.rstrip().endswith(('có', 'Có', 'không')):
        return 1.5
    if current.strip() == 'thấy' and previous.rstrip().endswith('cảm'):
        return 1.2
    if not _HAN.search(current):
        return 0.0
    a, b = simplify(previous), simplify(current)
    for meaning, words, value in WHOLE:
        if b in words:
            return value
    if not a or not b or not _HAN.fullmatch(a[-1]):
        return 0.0
    pair = a[-1] + b[0]
    for meaning, words, value in COMPLETIONS:
        if pair in words:
            return value
    # The kinship/intimacy root 'qin' in lexical compounds.
    if a[-1] == '亲' and known_word(pair):
        return -.8
    # Look up the English meanings rather than listing Chinese math tokens.
    for end in range(1, min(3, len(b)) + 1):
        meanings = cedict.glosses(a[-1] + b[:end])
        if 'acceleration' in meanings:
            return -4.1
        if 'symmetry' in meanings or 'symmetrical' in meanings:
            return -1.8
        if '(math.) logarithm' in meanings:
            return -1.7
        if 'multiplier' in meanings:
            return -.6
    if len(b) == 1:
        if b == '于':
            return .8 if current == '於' else .25
        if b == '为' and known_word(pair):
            return 2.4 if current == '爲' else (.6 if current == '為' else .25)
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, position = b'', 0
    else:
        _, tail, position = carry
    raw = prefix.token_bytes[-1]
    before = tail.decode('utf-8', errors='ignore')
    joined = (tail + raw).decode('utf-8', errors='ignore')
    current = joined[len(before):]
    value = predict(before, current, position)
    return (doc, (tail + raw)[-32:], position + 1), value

"""A spelling feature for z adjoining vowels and sonorants.

Short fragments containing oz are positive. Vowel+n/l/r+z clusters
are negative, especially when z ends the fragment. Longer tokens
are mostly suppressed. A little of this feature continues into
the next suffix token. Cyrillic з is matched by transliteration; ounce
units receive a separate positive value. These spelling patterns were
prominent in the harvested and training activations, not a shared topic.
"""
import unicodedata
READS = ()
WEIGHTS = {
    'o': 2.919,
    'n': -2.99,
    'l': -4.485,
    'r': -2.701,
    'e': 0.656,
    'u': 0.576,
    'a': 0.101,
    'unit': 1.741,
}
CYRILLIC = str.maketrans('зонлреуаи', 'zonlreuai')


def normalize(text):
    text = unicodedata.normalize('NFD', text.lower())
    unaccented = ''.join(c for c in text if not unicodedata.combining(c))
    return unaccented.translate(CYRILLIC)


def features(raw, previous, tail):
    s = normalize(raw)
    word = s.strip()
    j = s.find('z')
    f = {}
    if j >= 0:
        before = tail + s[:j]
        letter = before[-1:]
        vowel_before = before[-2:-1] in {'a', 'e', 'i', 'o', 'u'}
        length = len(word)
        end = j == len(s)-1
        if letter == 'o':
            scale = 0.45 if 'з' in raw.lower() else 1.0
            if length == 3:
                scale *= 0.8 if j == 0 else 0.55
                # The oz+e spelling is especially strong.
                if word == 'oze':
                    scale *= 3.6
            elif length >= 4:
                scale *= 0.03
            if before.endswith('oo') and length <= 3:
                scale *= 1.8
            f['o'] = scale
        elif letter in ('n', 'l', 'r'):
            scale = 1.0 if vowel_before else 0.16
            if not end:
                scale *= 0.55
            if length >= 4:
                scale *= 0.15
            if length >= 6:
                scale = 0.0
            f[letter] = scale
        elif letter in ('e', 'u', 'a'):
            scale = 1.0 if length <= (3 if letter == 'u' else 2) else 0.15
            if length >= 5:
                scale = 0.0
            if s.endswith('e') and length <= 3:
                scale *= 2.5
            f[letter] = scale
    unit_boundary = s[:1].isspace() or not previous[-1:].isalpha()
    if word in ('ounce', 'ounces') and unit_boundary:
        f['unit'] = 1.0
    return s, f


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    # A new packed document has no spelling history.
    if carry is None or carry[0] != doc:
        previous, tail, old_score = '', '', 0.0
    else:
        _, previous, tail, old_score = carry
    s, f = features(prefix.token_strings[-1], previous, tail)
    base = sum((WEIGHTS[k] * value for k, value in f.items()), 0.0)
    value = base
    if 'z' not in s and s[:1].isalpha() and previous.endswith('z'):
        value += old_score * (0.8 if tail.endswith('ooz') else 0.25)
    return (doc, s, (tail+s)[-16:], base), value

"""A sparse orthographic predictor, not a model simulation.

The strongest rules recognize Thai stacked vowel/tone signs (especially ื้อ),
opening title/comment syntax, Korean tense-ss syllable fragments, and a few
conspicuous lexical/glyph responses.
A small document-initial correction distinguishes indentation, digits, and
ordinary word fragments. Unrecognized text receives a near-zero value.
These are separate observed triggers, not a single semantic interpretation.
"""
import math

READS = ()


def opening_value(text):
    """The first token has no preceding linguistic context."""
    if text.startswith('<|'):
        return 3.16 if text == '<|endoftext|>' else 0.0
    if text == '//\n':
        return 3.83
    if text == '//':
        return -1.0
    if text == 'Title':
        return -0.53
    if text.startswith('#'):
        return -0.45
    if text.isspace():
        if '\t' in text:
            return 0.5
        if len(text) > 1:
            return 0.22
        return -0.16 if text == '\n' else -0.30
    if len(text) == 1 and text in '0123456789':
        n = int(text)
        return -0.60 / math.sqrt(n) if n else 0.0
    word = text.strip()
    if word in ('The', 'This', 'These', 'That', 'Those'):
        return 0.25
    if word.isascii() and word.isalpha():
        if len(word) == 1:
            return -0.35
        if text.startswith(' '):
            return -0.20 if len(word) < 4 else -0.08
        return -0.27 if len(word) < 4 else -0.18
    return -0.1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    _, tail, raw, previous, position = (
        (doc, '', b'', '', 0) if first else carry
    )
    token = prefix.token_strings[-1]
    b = prefix.token_bytes[-1]
    value = opening_value(token) if first else 0.002

    # Thai vowel sequences can cross token boundaries.
    if token in ('่', '้'):
        # Stacking a tone over a written vowel is especially salient.
        vowel = tail[-1:]
        if vowel == 'ื':
            value = 4.7
        elif vowel == 'ิ':
            value = 2.2
        elif vowel == 'ั':
            value = 1.0
        elif vowel == 'ึ':
            value = 1.3 if token == '้' else 0.55
        elif vowel == 'ุ':
            value = 1.0
        else:
            value = 0.25 if token == '้' else 0.0
    elif token.startswith('อ') and tail.endswith(('ื้', 'ื่', 'ื')):
        strength = 3.3 if tail.endswith('ื้') else 1.5
        if tail.endswith('เพื่'):          # เพื่อ: "for / in order to"
            strength = 2.3
        value = strength / len(token) ** 2
    elif token.startswith('ือ') and tail.endswith(('ร', 'ล')):
        if not tail.endswith('หร'):
            value = 2.5 / max(1, len(token) - 1)
    elif token in ('ั', 'ัก') and tail.endswith('ร'):
        value = 1.3 if len(token) == 1 else 2.7
    elif token in ('ิ', 'ุ', 'ำ') and tail.endswith('ร'):
        value = 0.7 if token == 'ำ' else 1.1
    elif token == 'ื':
        value = 0.7
    elif token == 'ื่':
        value = 0.35

    # A few lexical responses that do not form one semantic category.
    if token == '自由':                     # freedom
        value = -1.8
    elif token == '方便':                   # convenience
        value = 1.7
    elif token == '以便':                   # so as to
        value = 1.1
    elif token == '受理':                   # accepting a case or application
        value = 1.8
    elif len(token) >= 2 and set(token) == {'·'}:
        value = 0.41

    # Decode the newest character even when its bytes span several tokens.
    completed = (raw + b).decode('utf-8', 'replace')
    c = completed[-1:] or ' '
    if c == '\ue103':                     # fi-like private-use glyph in extracted text
        value = 2.0
    elif c == '駄':                       # kanji in 駄目 ("no good")
        value = -5.1
    elif b and 0x80 <= b[0] < 0xc0 and value == 0.002:
        value = 0.04
        # Unicode decomposes Hangul into onset, vowel, and final consonant.
        if '가' <= c <= '힣':
            syllable = ord(c) - ord('가')
            if syllable // 588 == 10 and syllable % 28 == 0:
                value = 2.0               # open syllables with tense ss
        elif c == '\ufffd':
            blob = raw + b
            j = len(blob) - 1
            while j > 0 and 0x80 <= blob[j] < 0xc0:
                j -= 1
            pending = blob[j:]
            if len(pending) == 2 and 0xe0 <= pending[0] < 0xf0:
                # Lowest code point consistent with the two bytes so far.
                low = ((pending[0] & 15) << 12) | ((pending[1] & 63) << 6)
                if 0xac00 <= low <= 0xd7a3 and (low - 0xac00) // 588 == 10:
                    value = 2.5           # a tense-ss Hangul prefix

    if token == ':' and previous == 'Title' and position <= 2:
        value = -5.22
    elif token == '//' and previous == '//\n':
        value = -0.74

    return (doc, (tail + token)[-12:], (raw + b)[-8:], token,
            position + 1), float(value)

