import unicodedata

READS = ()

# Thai combining marks (tone marks, vowel signs), e.g. the tone mark in ซื้อ or ื่ in เชื่อ.
THAI_MARKS = {c for c in map(chr, range(0x0E00, 0x0E80)) if unicodedata.category(c) in ("Mn", "Mc")}


def step(carry, prefix, upstream):
    """Mean-level predictor for layers.1.mlp.down_proj:927.

    The component is diffuse: its activation has mean ~0 and a long tail of sign-varying
    spikes. This program predicts only the conditional means it can name:
    - the first token of each document (after the packed-row reset) is pushed negative;
    - a Thai combining mark (tone mark or vowel sign, mid-word) is pushed positive;
    - the word 自由 ("freedom") is strongly negative.
    Everything else is predicted as 0.
    """
    docs = prefix.document_ids
    token = prefix.token_strings[-1]
    if len(docs) == 1 or docs[-1] != docs[-2]:
        return None, -0.17
    if token == "自由":
        return None, -2.1
    if any(c in THAI_MARKS for c in token):
        return None, 0.15
    return None, 0.0

