"""Approximate a script-sensitive typography signal.

Tildes in Chinese prose have a strong negative response; code tildes do not.
Yen signs and copyright marks also depend on the surrounding writing system.
Small boundary rules cover document-opening capitalization and markup.
Scattered lexical and incomplete-character responses are not modeled.
"""
import regex
import unicodedata

READS = ()
HAN = regex.compile(r'\p{Script=Han}')
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
HANGUL = regex.compile(r'\p{Script=Hangul}')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, (), '', 0, '', True)
    _, history, tail, position, previous, only_cr = carry
    recent = history[-16:]
    count = max(1, len(recent))
    han = sum(v[0] for v in recent) / count
    kana = sum(v[1] for v in recent) / count
    hangul = sum(v[2] for v in recent) / count
    long_han = sum(v[0] for v in history) / max(1, len(history))
    s = prefix.token_strings[-1]
    w = s.strip()
    value = 0.0

    # The boundary response is strongest for unspaced, capitalized openings.
    if position == 0 and w:
        if not s.startswith(' ') and w[0].isupper():
            value = -0.30
        elif not s.startswith(' ') and w[0].islower():
            value = -0.07
        elif unicodedata.category(w[0]) == 'Sm':
            value = -0.45 if not s.startswith(' ') else 0.1
        elif unicodedata.category(w[0]) == 'Ps':
            value = -0.4 if not s.startswith(' ') else 0.0
        if w.startswith('#'):
            value = -0.48
        if s in ('This', 'These'):
            value = -0.96
    if s in ('import', 'package', '#include'):
        value = -0.65 if position == 0 else -0.16
    if s == '<|im_start|>':
        value = -0.48 if position == 0 else 0.0
    elif s == '<|im_end|>':
        value = 0.06
    elif s == '<|endoftext|>':
        value = -1.29 if position == 0 else -0.024
    if s == ':' and position == 1 and previous == 'Title':
        value = 1.87
    if s == 'issue' and tail.endswith('<issue_start><'):
        value = 1.73

    # Attached prose waves differ from separated code/math tildes.
    if w and set(w) <= {'~'}:
        context = min(1.0, 4.0 * han)
        if s.startswith(' '):
            value = 0.06 - 0.1 * han - 0.5 * hangul
        elif s.endswith('\n'):
            value = 0.04 - 0.75 * han
        elif len(w) > 1:
            value = 0.03 - 0.8 * han
        else:
            value = (0.06 - 0.6 * context - 0.65 * han
                     + 0.4 * kana * context - 0.5 * hangul
                     - 0.2 * previous.isdigit() * context)
    elif w == '～':
        value = 0.03 - 0.75 * han + 0.2 * kana
    elif w == '〜':
        value = -0.03 - 0.1 * han - 0.15 * previous.isdigit()
    elif w == '￥':
        value = -0.8 - 2.0 * han - 0.5 * kana
    elif w == '¥':
        value = 0.12 if tail.endswith('â‰') else -1.3
    elif w == '¤':
        value = 0.03 - 1.8 * han
    elif w == '©':
        value = 0.12 - 1.8 * long_han - 0.3 * kana
    elif w == '\u200b':
        value = 0.22 - 0.4 * han
        if previous.endswith('\n') and han > 0.3:
            value = -0.7 - 0.6 * han
    if s == '\r' and only_cr:
        value = -2.60

    flags = (bool(HAN.search(s)), bool(KANA.search(s)),
             bool(HANGUL.search(s)))
    history = (history + (flags,))[-64:]
    return (doc, history, (tail + s)[-64:], position + 1, s,
            only_cr and s == '\r'), float(value)

