"""Layer-1 MLP neuron 928 (down_proj), the part of its output that depends on the
first token of a document.

Mostly this component is near zero: a long tail of small, token-specific values.
Its clearest structure is at the first token of each document (or of a packed row),
where no text precedes the token, so the token alone sets the value:
  * an opener of a sentence, heading or code line (a capitalised word with no leading
    space, '#', '<|im_start|>', brackets or quotes) pushes it negative, about -0.3;
  * a lone space or a lowercase preposition (of, in, into, with, that, not, ...)
    pushes it positive, about +0.3: the text is continuing mid-sentence.
Elsewhere it is negative on a few symbols and code or URL fragments.
"""

READS = ()

PREPOSITIONS = {"of", "in", "into", "with", "on", "at", "for", "from", "that", "not", "all",
                "if", "as", "so", "which", "are", "have", "what", "a"}
MARKUP = "#<([{\"/|\\*@"
SYMBOLS = {"￥": -2.0, "~": -0.2}
CODE_OR_URL = {"import", "package", "#include", "www", ".com", ".github"}


def start_value(s):
    """Value at the first token of a document, which has no preceding text."""
    core = s.lstrip(" ")
    lead = len(s) > len(core)
    if s == " ":
        return 0.3
    if not core:
        return -0.2
    c = core[0]
    if c == "\n":
        return -0.2
    if c.isupper():
        return 0.0 if lead else -0.3
    if c.isdigit():
        return -0.06
    if c.isascii() and c.islower():
        return 0.3 if lead and core in PREPOSITIONS else -0.05
    if c in MARKUP:
        return -0.3
    if not c.isascii():
        return -0.13
    return 0.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, float(start_value(s))
    if s in SYMBOLS:
        return None, float(SYMBOLS[s])
    if s.strip() in CODE_OR_URL:
        return None, -0.2
    return None, 0.0

programs.sol:
"""A ram/gram fragment detector, not a semantic category.

Short spelling fragments elicit a large negative value; whole words containing
those letters usually elicit less. The rule also recognizes a pattern completed
across tokens, and short suffixes attached to it. Transliteration extends this
approximation across alphabets. Common lexicalized words are damped; the trace
fades as more letters follow. Strengths are rounded training-category averages.
Small case/spacing offsets approximate the separate document-start effect.
"""
import re
from functools import lru_cache
from anyascii import anyascii
from wordfreq import zipf_frequency

READS = ()
# Include the silent g of diaphragm, and weaker other-vowel variants.
RHOTIC_M = re.compile(r'r(?:ag?|[eoiu])m')


@lru_cache(None)
def latin(text):
    # anyascii otherwise drops Arabic alif, obscuring the long a in ram.
    return anyascii(text.replace('ا', 'a').replace('آ', 'a')).lower()


@lru_cache(None)
def frequency(word, language='en'):
    return zipf_frequency(word, language)


def lexicalized(word):
    return word.startswith(('program', 'param')) or 'frame' in word


def response(text, previous):
    """Return the spelling response, and the current alphabetic word tail."""
    s = latin(text)
    joins_word = bool(re.match('[a-z]', s))
    word = previous + s if joins_word else s
    tail = re.search('[a-z]+$', word)
    new_word = tail.group()[-40:] if tail else ''
    direct = RHOTIC_M.search(s)
    hits = list(RHOTIC_M.finditer(word))
    hit = hits[-1] if hits else None
    value = None

    if direct:
        piece = next(p for p in re.findall('[a-z]+', s)
                     if direct.group() in p)
        after = len(piece) - piece.index(direct.group()) - len(direct.group())
        fragment = joins_word and not text[:1].isupper()
        capital = text.lstrip()[:1].isupper()
        if (lexicalized(piece) or frequency(piece) >= 5.5
                or (piece == 'aram' and previous == 'p')):
            strength = 0.0
        elif direct.group() not in ('ram', 'ragm'):
            strength = 0.05
        elif after == 0:
            if piece == 'gram' or (piece == 'ram' and previous.endswith('g')):
                strength = 8.9 if capital and not joins_word else (
                    6.6 if joins_word else 4.4)
            elif len(piece) <= 4:
                strength = 4.4
            else:
                strength = 4.5 if fragment else (3.2 if capital else 1.3)
        elif after == 1:
            strength = 4.4 if fragment else 1.3
        else:
            strength = 0.35
        value = -strength

    elif hit and joins_word:
        after = len(word) - hit.end()
        if hit.end() > len(previous):
            # A new r-vowel-m spelling has just crossed the token boundary.
            strength = (6.1 if after == 0 else 3.4 if after <= 2 else 0.4)
            if hit.group() not in ('ram', 'ragm'):
                strength = 0.25
            complete = re.match('[a-z]+', word).group()
            if frequency(complete) >= 5.5 or frequency(complete, 'pt') >= 5.0:
                strength *= 0.15  # common words and Portuguese verb inflections
            if s.startswith('m') and text.isascii():
                strength *= 0.55
            if hit.start() > 0 and word[hit.start() - 1] == 'g':
                strength *= 1.5
            value = -strength
        elif hit.group() in ('ram', 'ragm') and after <= 6 and s.isalpha():
            # Short continuations, especially vowels or a doubled m, retain it.
            if len(s) == 1 and s in 'aeiou':
                strength = 4.3
            elif s in ('m', 'ma', 'me', 'mi', 'mo', 'mu'):
                strength = 5.5
            elif s == 's':
                strength = 3.0
            else:
                strength = 1.1 if len(s) <= 3 else 0.4
            strength *= 0.2 ** (len(previous) - hit.end())
            if lexicalized(previous):
                strength *= 0.15
            value = -strength
    return value, new_word


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    reset = carry is None or carry[0] != doc
    previous = '' if reset else carry[1]
    first = reset or carry[2]
    value, word = response(text, previous)
    if value is None:
        stripped = text.lstrip()
        value = 0.001
        if first:
            if text.startswith(' ') and stripped[:1].islower():
                value = -0.28
            elif stripped[:1].isupper() and not text.startswith(' '):
                value = 0.02
            elif stripped[:1].islower() and not text.startswith(' '):
                value = -0.02
            else:
                value = -0.21
    return (doc, word, text == '<|endoftext|>'), float(value)

