"""Letter-n detector (negative), layers.1.mlp.down_proj:931, plus the word 'name'."""

READS = ()
ALNUM_OR_BACKSLASH = set("\\")
NAME_WORDS = {"name", " name", "NAME", " NAME", "Name", " Name"}


def _only_n(s):
