    'know see check test determine verify wonder ask '
    'decide ascertain detect '
    .split()
)
CERTAINTY = set(
    'sure certain unsure uncertain clear unclear evident obvious '
    'aware convinced confident '
    .split()
)
LIGHT_VERBS = set(
    'be do have get take give make put '
    'keep leave hold use go come work play '
    'mean '
    .split()
)
ASSERTIONS = set(
    'assert affirm allege contend maintain posit postulate hypothesize '
    'infer presume speculate opine conjecture deduce argue forecast '
    'predict estimate '
    .split()
)
PROPOSITIONS = set(
    'evidence belief claim conclusion consensus assumption indication hypothesis '
    .split()
)
PREPOSITIONS = set(
    'of in on at for from with to '
    'by as than but except '
    .split()
)
