    r'(?:di[rctz]|dij|sai|sav|sach|sab|ver$|veder|pens|cre[do]|cred|croi|concl|'
    r'montr|demontr|demostr|demonstr|afferm|affirm|sostien|ricord|lembr|'
    r'sap|sper|sent|chiar|revel|observ|parec|garanti|certifi|assicur)')

