    if s == '··' and before.endswith('··'):
        return 0.53432  # dot leader
    if count == 0 and s == '**':
        return 1.085  # initial bold
    if s == ':' and count < 4 and before == 'Title':
        return -2.236  # initial title colon
    return 0.00023  # other


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
