COUNT_MODIFIERS = {'each', 'every', 'both', 'multiple', 'several', 'many',
                   'different', 'various'}
QUANTITY_MARKERS = set('两兩半这這那哪几幾每各多双雙')
# Values without/with an explicit count or distributive modifier.
PARTITIVES = {
    'pair': (-1.85, -3.06), 'pairs': (-1.85, -3.06),
    'piece': (-0.43, -0.84), 'pieces': (-0.65, -2.24),
    'set': (0.0, -0.50), 'sets': (-0.41, -2.78),
    'type': (-0.24, -1.45), 'types': (-0.08, -0.57),
}


def quantity_char(c):
    return c.isnumeric() or c in QUANTITY_MARKERS


@lru_cache(maxsize=4096)
def counter_gloss(c):
    definitions = cedict.glosses(c) + jmdict.glosses(c)
    return ' '.join(g.lower() for g in definitions
                    if 'classifier' in g.lower() or 'counter' in g.lower())


def predict(previous, token):
    s = token.strip()
    lower = s.lower()
    if not s:
        return 0.0
    if (s == ',' and token.startswith(' ')
            and previous.rstrip()[-1:].isdigit()):
        return 0.50
    if token.isascii() and lower not in {'of', 'end', 'ends', 'thing', 'people'}:
        return 0.0
    if lower in {'of', 'end', 'ends', 'thing', 'people'}:
        words = re.findall(r'[A-Za-z]+|\d+', previous.lower())
        w = words[-1] if words else ''
        modifier = words[-2] if len(words) > 1 else ''
        counted = (modifier.isdigit() or modifier in CARDINALS
                   or modifier in COUNT_MODIFIERS)
        if lower == 'of':
            if w in PARTITIVES:
                return PARTITIVES[w][counted]
            if w in {'dozens', 'hundreds', 'thousands', 'millions',
                     'billions', 'trillions'}:
                return -1.10
            if w == 'plurality':
                return -1.90
            if w in {'group', 'groups', 'couple', 'couples'}:
                return -0.11
            if w in {'kind', 'kinds', 'sort', 'sorts'}:
                return -0.15
            if w in {'ounce', 'ounces', 'cup', 'cups', 'sheet', 'sheets',
                     'ton', 'tons', 'bottle', 'bottles', 'glass', 'glasses'}:
                return -0.25
            if w in {'end', 'ends'} and modifier in {'one', 'each', 'both',
                                                     'two', 'other'}:
                return -0.93
        if lower == 'end':
            return {'one': -2.41, 'each': -2.70, 'other': -0.76}.get(w, 0.0)
        if lower == 'ends' and w in {'both', 'two'}:
            return -2.62
        if lower == 'thing' and w == 'one':
            return 1.47
        if lower == 'people' and (w.isdigit() or w in CARDINALS):
            return -0.58
        return 0.0

    # The quantity may precede this token or be joined to its beginning.
    i = 0
    while i < len(s) and quantity_char(s[i]):
        i += 1
    if i:
        s = s[i:]
    elif (not previous.rstrip()
          or not quantity_char(previous.rstrip()[-1])):
        return 0.0
    joined = i > 0
    if s == '円':
        return 0.90
    if s in {'つ', 'つの'}:
        return -0.43
    if s in {'号楼', '號樓'}:
        return -1.85
    if s in {'个人', '個人'}:
        return -0.10 if joined else -2.30
    if len(s) != 1 or s in '年月日天时時分秒岁歳':
        return 0.0
    gloss = counter_gloss(s)
    if not gloss:
        return 0.0
    japanese = regex.search(r'[\p{Hiragana}\p{Katakana}]', previous) is not None
    if 'numbered' in gloss:
        return -1.48 if japanese or joined else -2.95
    if 'handful' in gloss or 'things with handles' in gloss:
        return -5.0 if joined else -3.0
    if 'mouthful' in gloss:
        return -2.50 if joined else 0.0
    if s in '只隻头頭':             # bird/animal and head-of-livestock counters
        return -2.80 if joined else -3.30
    if s in '对對':                 # generic paired sets, not pairs of shoes etc.
        return -6.06
    if 'coin' in gloss:
        return -2.0 if joined else -3.20
    if 'flat object' in gloss or 'sheet' in gloss:
        return -0.66
    if 'honorific' in gloss:
        return -0.15
    if 'people' in gloss or 'person' in gloss:
        if s == '人':
            return -0.05 if joined else -0.38
        return -1.52
    if 'no specific classifier' in gloss or 'general-purpose' in gloss:
        return -0.05 if joined else (-0.43 if japanese else -0.81)
    if 'long thin' in gloss or 'long slender' in gloss:
        return -0.62
    return -0.10 if joined else -0.29


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = predict(previous, token)
    return (doc, (previous + token)[-80:]), float(value)

"""An approximation of negative responses to English action/abstract nouns.

The strongest pattern is bare nominalizations, rather than nouns with an
article or possessive. This deliberately uses word classes, not token IDs.

WordNet noun meanings and productive noun endings supply a word score;
uncommon abstract/action words get larger negative responses.
Articles/possessives, capitalization and auxiliaries weaken it; prepositions,
conjunctions and a noun-ending subword strengthen it. A following 'of' keeps
part of the previous response. Nonalphabetic/non-ASCII words get zero.
State resets between documents.
"""
import re
from functools import lru_cache
import wordnet
from wordfreq import zipf_frequency

READS = ()
DETERMINERS = set((
    'the a an this that these those my your his her its our their '
    'each every any some no another such'
).split())
PREPOSITIONS = set((
    'of for by without with during through upon after before from '
    'in on at via into under over'
).split())
AUXILIARIES = set((
    'am is are was were be been being have has had do does did '
    'can could shall should will would may might must'
).split())
PRONOUNS = set('i you he she it we they who which'.split())
# Each noun class has a base weight and an extra weight for uncommon words.
NOUN_MEANINGS = {
    'act': (-.03, -.19), 'process': (-.18, -.16),
    'state': (-.03, -.10), 'attribute': (-.01, -.13),
    'feeling': (-.05, -.13), 'phenomenon': (-.025, -.045),
    'event': (-.025, 0), 'group': (.015, 0), 'time': (.02, 0),
}
ENDINGS = {
    'ing': -.044, 'tion': -.18, 'sion': -.17, 'ment': -.16,
    'ance': -.10, 'ence': -.13, 'ness': -.31, 'ity': -.24,
    'ism': -.26, 'age': -.125, 'ure': -.045, 'ship': -.43, 'sis': -.36,
}
NOMINAL = (
    'tion', 'sion', 'ment', 'ance', 'ence', 'ness', 'ity', 'ism', 'ship', 'sis'
)

@lru_cache(None)
def word_score(w):
    cats = wordnet.categories(w)
    pos = wordnet.parts_of_speech(w)
    rarity = max(0.0, 5.2 - zipf_frequency(w, 'en')) / 2
    score = -.009 - .00215 * min(len(w), 20)
    score += sum(base + rarity * extra
                 for c, (base, extra) in NOUN_MEANINGS.items()
                 if 'noun.' + c in cats)
    score += sum(v for end, v in ENDINGS.items() if w.endswith(end))
    score -= rarity * (
        .06 * w.endswith(NOMINAL) + .09 * w.endswith('ing')
    )
    score += -.02 * ('noun' in pos) + .028 * ('verb' in pos)
    score += .014 * ('adjective' in pos)
    return score

@lru_cache(None)
def is_adjective(w):
    return w.isascii() and 'adjective' in wordnet.parts_of_speech(w)

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    if start:
        word, previous, gap, last = '', [], '', 0.0
    else:
        _, word, previous, gap, last = carry
    token = prefix.token_strings[-1]
    continuation = bool(word and token and token[0].isalpha())
    for part in re.findall(r'[^\W\d_]+|[\W\d_]+', token):
        if part[0].isalpha():
            word += part
        else:
            if word:
                previous = (previous + [word.lower()])[-3:]
                word = ''
            gap = part
    w = word.lower()
    p = previous[-1] if previous else ''
    plural = w.endswith('s') and not w.endswith(('ss','sis','ness'))
    scale = 1.0 + .575 * continuation - .685 * plural - .15 * start
    scale -= .405 * word[:1].isupper() + .155 * word.isupper()
    for distance, weight in enumerate((.56, .485, .21), 1):
        if len(previous) >= distance and previous[-distance] in DETERMINERS:
            scale -= weight
    scale += .465 * (p in PREPOSITIONS) + .28 * (p in {'and','or'})
    scale -= .34 * (p in AUXILIARIES) + .13 * (p in PRONOUNS)
    scale -= .59 * bool(gap.strip()) + .09 * ('_' in gap or '.' in gap)
    scale -= .125 * (p in {'a','an'})
    scale += .125 * is_adjective(p)
    if not w.isascii() or not w.isalpha():
        value = 0.0
    elif w == 'of':
        value = .4 * last
    else:
        score = word_score(w) + .037 * plural - .015 * w.endswith('ed')
        value = .02 + score * scale
    return (doc, word, previous, gap, value), float(value)

"""Local formulaic expressions, especially thanks and good wishes.

The large negative responses are on the completion of conventional expressions:
thank you, good luck/morning/night, and similar social formulae. There are
smaller responses to 'all day/night', 'no need', and adjective--noun
collocations. Both signs occur: good news is negative, but good faith is positive.
These are local lexical rules, not a general sentiment score.
State remembers the previous two token strings, and resets at document breaks.
Uncovered tokens receive zero.
"""
READS = ()

# The second word of a conventional expression carries the response.
SOCIAL = {
    'good': {
        'luck': -10.4, 'morning': -8.3, 'night': -8.0,
        'bye': -9.0, 'day': -2.1, 'dreams': -3.2,
        'job': -1.2, 'work': -2.3,
    },
    'happy': {'birthday': -7.8, 'holidays': -2.1},
    'best': {'regards': -7.7, 'wishes': -6.1},
    'kind': {'regards': -4.0},
    'warm': {'regards': -3.6},
    'many': {'thanks': -3.7},
    'well': {'done': -4.0, 'played': -3.9},
    'nice': {'work': -4.6, 'day': -1.5},
    'god': {'bless': -3.0},
    'merry': {'christmas': -2.5},
    'new': {'year': -2.5},
}

# A few other fixed combinations use the same local signal.
COLLOCATIONS = {
    'all': {
        'day': -5.0, 'night': -7.0, 'week': -4.4, 'year': -3.1,
        'afternoon': -2.5, 'season': -2.1, 'time': 3.9,
        'times': 1.0, 'right': -3.3, 'rights': -1.4,
        'things': -0.9, 'over': -0.4,
    },
    'no': {'need': -4.0, 'more': -0.7},
    'good': {
        'news': -6.3, 'faith': 2.5, 'time': 1.8, 'place': 1.8,
        'choice': -2.3, 'eye': -4.3, 'order': 2.1,
        'practice': -1.5, 'old': -1.1, 'thing': 0.5,
    },
    'bad': {'news': -6.1, 'luck': -3.7, 'faith': 2.4},
    'great': {
        'news': -4.6, 'white': 2.7, 'circle': 3.3,
        'time': 1.6, 'place': 1.2, 'job': -0.8,
    },
    'best': {'choice': -2.3, 'time': 1.7, 'interests': -1.0},
    'right': {'choice': -1.9},
    'common': {'sense': -1.6},
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    prev, before = ('', '') if first else carry[1:]
    word = token.strip().lstrip('-_').lower()
    modifier = prev.strip().lower()
    value = 0.0

    if modifier == 'thank' and word == 'you':
        # Direct thanks is stronger than 'I/we thank you' or 'to thank you'.
        if prev.strip().isupper():
            value = -5.8
        elif prev.strip()[0].isupper():
            value = -9.1
        elif before.strip().lower() in {'i', 'we', 'to'}:
            value = -4.1
        elif before.strip().lower() in {'a', 'big', 'special'}:
            value = -6.0
        else:
            value = -8.0
    else:
        value = SOCIAL.get(modifier, {}).get(word, 0.0)
        value = COLLOCATIONS.get(modifier, {}).get(word, value)
        # Capitalized Regards is a distinct, weaker completion.
        if modifier == 'best' and token.strip() == 'Regards':
            value = -1.8
        if modifier == 'no' and word == 'need' and prev.strip() == 'No':
            value = -5.5

    # A few salutations are split inside the word by the tokenizer.
    if modifier == 'by' and token == 'e':
        value = -5.9
    if modifier in {'good-b', 'good_b'} and word == 'ye':
        value = -12.0
    if before.strip().lower() == 'good' and modifier == '-b' and word == 'ye':
        value = -12.0
    if modifier == 'bon' and word == 'jour':
        value = -3.5
    if modifier == 'erry' and word == 'christmas':
        value = -2.5
    if word == 'goodbye':
        value = -3.0

    if word == 'you' and modifier != 'thank':
        if modifier in {
            'give', 'gives', 'gave', 'giving', 'tell', 'told', 'telling'
        }:
            value = 1.05
        elif modifier == 'sure':
            value = 0.85
        elif modifier in {'help', 'do', 'so'}:
            value = 0.33
        elif modifier in {'see', 'of'}:
            value = -0.9
        elif modifier == 'meet':
            value = -2.5

    if first:
        value = {'Hi': 2.1, 'Hello': 3.0, 'Welcome': 1.6}.get(token, 0.0)
    return (doc, token, prev), value

"""Approximate a spelling-sensitive win/won feature, including won't.

Win uses preceding verb cues, capitalization, and word boundaries to
adjust its strength. Inflected forms have their own strengths. Split
spellings such as w + on and Win + ning also respond, with smaller
responses for www and short w-syllables. All other positions predict
zero. Only the current and previous token are used, within a document.
"""
READS = ()

VERB_CUES = {'can', 'could', 'will', 'would', 'may', 'might', 'must',
             'should', 'does', 'did', 'and'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = ''
    if prefix.position and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]
    word = token.strip().lstrip('-')
    lower = word.lower()
    embedded = (token[:1].isalpha() and previous[-1:].isalpha())
    before = previous.strip().lower()
    value = 0.0

    if lower == 'win':
        if word.isupper():
            value = 3.2
        elif word[:1].isupper():
            value = 8.9 if before == 'to' else 5.5
        elif embedded:
            value = 0.2 if before.endswith('t') else 2.6
        elif token.startswith('-'):
            value = 8.5
        elif before == 'to':
            value = 8.9
        elif before in VERB_CUES:
            value = 7.8
        else:
            value = 5.3
    elif lower == 'won':
        value = 4.8 if word.isupper() else 9.0
    elif lower in {'wins', 'winning', 'winner', 'winners', 'winnings'}:
        value = {'wins': 7.0, 'winning': 8.0, 'winner': 5.2,
                 'winners': 4.3, 'winnings': 3.2}[lower]
    elif lower == 'www':
        value = 1.9 if not token.startswith(' ') else 0.3
    elif lower in {'wo', 'woo'}:
        value = 2.3 if embedded else 0.9
    elif lower in {'wa', 'wah', 'wow'}:
        value = 2.0 if lower == 'wah' else 0.8
    elif lower in {'wine', 'wines'}:
        value = 1.0
    # A word can be split by the tokenizer: Win + ning, w + on, etc.
    if not token.startswith(' ') and previous:
        if before == 'win' and lower in {'ning', 'ner', 'ners'}:
            value = 12.0 if lower == 'ning' else 8.0
        elif previous.lower().endswith('w') and token[:1].islower():
            if lower in {'in', 'on'}:
                value = 8.0 if lower == 'in' else 10.0
            elif (lower.startswith(('in', 'on')) and len(lower) > 2
                  and lower[2] in 'aeiouyn') or lower.startswith('ong'):
                value = 5.0
            elif lower in {'oo', 'oon', 'oh', 'ohn', 'under'}:
                value = 5.0
            elif lower.startswith('o') and not lower.startswith(('ood', 'ow')):
                value = 0.8
            # The t/s + w clusters do not behave like a free w onset.
            if before.endswith(('tw', 'sw')):
                value *= 0.15
    if token == '-w':
        value = 1.4
    return None, value

"""Approximate a mixed separator feature.

Negative values mark commas in short parenthesized arguments or coordinates,
most strongly after a single number or identifier.  Ordinary prose commas are
nearly neutral.  Positive values mark repeated/indented blank or structural
lines, with a separate positive response to Java's @Override annotation.
A small bracket stack and the last two lines supply context; they reset at
new documents.  Other token-specific variation, including document-start
outliers, is not modeled.
"""
import re

READS = ()


def comma_value(frame, position, token):
    if frame is None:
        return 0.01
    kind, opened, commas, argument, attached = frame
    age = position - opened
    if age > 32:
        return 0.0
    word = bool(re.fullmatch(r'[\w.$]+', argument))
    spaces = argument.strip().count(' ')
    if kind == '{':
        return -0.03 if word else 0.06
    if kind == '[':
        return (-0.18 if age <= 2 else -0.10) if word else -0.03
    number = argument.strip().lstrip('+-').replace('.', '', 1)
    if commas == 0 and number.isdigit():
        return -0.65
    if (commas == 0 and age <= 20
            and argument.lstrip().startswith(("'", '"'))):
        return -0.43
    if word:
        if len(argument) == 1:
            value = -0.61 if argument.isdigit() else -0.47
        else:
            value = -0.49 if attached else -0.20
        if any(ch.isalpha() for ch in token):
            value *= 0.60 if age <= 2 else 0.40
        return value / (1 + 2 * commas)
    if not attached and spaces:
        return -0.02
    if age <= 8:
        return -0.32 if not spaces else -0.17 / spaces ** 0.5
    return -0.10 if len(argument) <= 58 else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, [], '', '', '', 0)
    _, stack, line, prior_line, previous, position = carry
    value = 0.0

    # A bracket frame remembers the text and commas inside that argument list.
    for j, ch in enumerate(token):
        if ch == ',':
            frame = list(stack[-1]) if stack else None
            value = comma_value(frame, position, token)
            if stack:
                stack[-1][2] += 1
        if ch in '([{':
            before = (line + token[:j])[-1:]
            attached = before.isalnum() or bool(before and before in '_.)(')
            stack.append([ch, position, 0, '', attached])
        elif ch in ')]}':
            wanted = {')': '(', ']': '[', '}': '{'}[ch]
            for k in range(len(stack) - 1, -1, -1):
                if stack[k][0] == wanted:
                    stack = stack[:k]
                    break
        elif stack and ch != ',':
            stack[-1][3] = (stack[-1][3] + ch)[-160:]

    if '\n' in token and ',' not in token:
        marker = token.strip()
        first_line = token.split('\n')[0]
        blank = not (line + first_line).strip()
        after_blank = not line.strip() and not prior_line.strip() and position > 0
        indentation = len(line) + token.count(' ') if blank else token.count(' ')
        if blank and indentation >= 5 and after_blank:
            value = 1.9 if indentation <= 14 else 1.5
        elif after_blank:
            if marker in ('//', '--'):
                value = 1.6
            elif marker in ('{', '}', '*', '+', '-', '>', '#'):
                value = 1.3
            elif not marker:
                value = 1.1 if token.strip('\r\n') else 0.66
            else:
                value = 0.15
        elif previous == token:
            value = 0.15 if marker in ('{', '}') else 0.74
        elif indentation >= 5 and len(prior_line.strip()) <= 6:
            value = 0.23
        else:
            value = -0.06 if '\t' in token else 0.0
        # A horizontal rule completed by this newline.
        rule = (line + first_line).strip()
        if re.fullmatch(r'([#*=_-])\1{7,}', rule):
            value = 0.65
        if prior_line.lstrip().startswith('/**') and marker == '*':
            value = 1.1

    if token.lstrip('@') == 'Override' and (
        token.startswith('@') or previous.rstrip().endswith('@')
    ):
        value = 0.76

    line = (line + token)[-256:]
    if '\n' in line:
        parts = line.rsplit('\n', 2)
        prior_line, line = parts[-2:]
    return (doc, stack, line, prior_line, token, position + 1), float(value)

"""Approximate a short-lived r trace in an unfinished word.

The next two alphabetic pieces after a single r tend to be positive;
short words and short continuation pieces have the strongest response.
Further r's suppress this response.  There is also a digit-after-6
response and a negative offset at the start of a row or document.
"""
import unicodedata

READS = ()


def count_r(text):
    text = unicodedata.normalize('NFD', text).casefold()
    return sum(c in 'rрر' for c in text)  # Latin, Cyrillic, Arabic r.


def word_char(c):
    return c.isalpha() or unicodedata.category(c).startswith('M')


def step(carry, prefix, upstream):
    s, doc = prefix.token_strings[-1], prefix.document_ids[-1]
    row_start = carry is None
    first = row_start or carry[0] != doc
    if first:
        count, age, length, previous_digit = 0, 9, 0, ''
    else:
        _, count, age, length, previous_digit = carry
    r, size = count_r(s), len(s.strip())
    if not s or not word_char(s[0]):
        count, age, length = 0, 9, 0
    value = 0.0
    if age < 2 and r == 0:
        if count == 1:
            if length <= 5:
                value = 0.48 if size <= 4 else 0.23
            else:
                value = 0.29 if size <= 2 else 0.15
                if length > 7 and size > 2:
                    value = 0.08
        elif count > 1 and age == 1:
            value = 0.20
    elif age == 2 and count == 1 and r == 0:
        value = 0.09
    if age < 2 and r and count > 1:
        value = -0.13
    if previous_digit == '6' and len(s) == 1 and s in '0123456789':
        value = 0.82 - 0.05 * int(s) - (0.25 if s == '6' else 0.0)
    if first:
        if row_start:
            value = -0.59 if r and size <= 6 else -0.30
        else:
            value = -0.62 if size <= 4 else (-0.44 if size <= 7 else -0.20)
    # Keep just the final alphabetic run: punctuation and spaces end words.
    if s and word_char(s[-1]):
        tail = s
        for i in range(len(s) - 1, -1, -1):
            if not word_char(s[i]):
                tail = s[i + 1:]
                break
        if tail != s:
            count, age, length = 0, 9, 0
        nr = count_r(tail)
        count, length = count + nr, length + len(tail)
        age = 0 if nr else age + 1
    else:
        count, age, length = 0, 9, 0
    previous_digit = s if len(s) == 1 and s in '0123456789' else ''
    return (doc, count, age, length, previous_digit), value

"""A multilingual first-person-plural detector.

Object, subject and possessive pronouns have a negative response, with
language-dependent strengths. The response also marks Romance plural verb
endings, English auxiliaries after 'we', and the contraction in 'let's'.
Word boundaries prevent mistaking the end of 'virus' for 'us'; US is not us.
These are surface-form heuristics, not a full grammatical analysis.
"""
import re

READS = ()
LETTERS = re.compile(r'[^\W\d_]+$')
PUNCTUATION = ' \t\r\n"“”‘’()[]{}:;,.!?'

# First-person-plural pronouns and possessive stems, grouped by language.
PRONOUNS = {
    'wir': -6.1, 'uns': -6.8,
    'nous': -6.0, 'nos': -6.0, 'notre': -4.1,
    'noi': -7.0, 'ci': -5.5,
    'nosotros': -7.0, 'nosotras': -7.0, 'nós': -5.5,
    'wij': -5.0, 'ons': -7.0, 'onze': -4.0, 'vi': -2.2,
    'мы': -5.5, 'нас': -7.5, 'нам': -4.3, 'нами': -5.0,
}

# The most common auxiliaries following the English plural subject.
AFTER_WE = {
    'are': -2.8, 'were': -2.0, 'had': -1.8,
    'have': -1.0, 'need': -1.0, 'can': -1.35, 'will': -1.3,
    'could': -0.95, 'should': -1.05, 'must': -1.05,
    'do': -0.55, 'did': -0.8, 'may': -0.3,
    'might': -0.6, 'would': -0.4, 'shall': -0.6,
    'also': -1.45, 'cannot': -1.5,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '')
    _, previous_word, tail = carry
    token = prefix.token_strings[-1]
    text = tail + token
    match = LETTERS.search(text.rstrip(PUNCTUATION))
    fresh_word = match is not None and match.end() > len(tail)
    word = match.group().lower() if fresh_word else ''
    raw = match.group() if fresh_word else ''
    value = PRONOUNS.get(word, 0.0)

    if word == 'we' and raw != 'WE':
        value = -1.4 if raw == 'We' else -2.0
    elif word == 'us' and raw != 'US':
        value = -1.7 if raw == 'Us' else -4.4
    elif word == 'our':
        value = -2.9 if raw == 'Our' else -3.1
    elif word in {'ours', 'ourselves'}:
        value = -2.3

    if re.fullmatch(r'unser(?:e[rmns]?)?', word):
        value = -3.9
    elif re.fullmatch(r'nuestr[ao]s?|noss[ao]s?', word):
        value = -4.8
    elif re.fullmatch(r'nost(?:r[aoie])?', word):
        value = -6.5 if word == 'nostri' else -4.8
    elif re.fullmatch(r'наш(?:а|е|и|у|его|ей|ему|им|ими|их|ем)?', word):
        value = -6.0 if word == 'наш' else -3.5
    if word == 'мы' and token.strip().lower() == 'ы':
        value = -8.5

    # Merged Chinese tokens can include words on either side of 'we'.
    for pronoun, strength in [('我们', -2.3), ('咱们', -2.3),
                              ('我們', -3.5), ('咱們', -3.5)]:
        start = text.rfind(pronoun)
        if start >= 0 and start + len(pronoun) > len(tail):
            value = strength
    if fresh_word and word.startswith('우리는'):
        value = -5.0
    elif fresh_word and word.startswith('우리'):
        value = -1.3
    if re.search(r'chúng\s+(tôi|ta)$', text, re.I):
        value = -5.0

    # Suffix tokens that finish common first-person-plural verb forms.
    ending = token.lower()
    if ending in {'iamo', 'amo'} and word.endswith(
            ('iamo', 'avamo', 'evamo', 'ivamo')):
        value = -4.2 if ending == 'iamo' else -6.3
    elif ending == 'mo' and word.endswith(('remmo', 'ammo', 'emmo', 'immo')):
        value = -6.5
    elif ending in {'amos', 'emos', 'imos', 'aremos', 'eremos', 'iremos'}:
        value = -3.4
    elif ending == 'ons' and re.search(r'\bnous\b', tail, re.I):
        value = -1.8

    if re.search(r"\blet['’]s$", text, re.I):
        value = -1.9
    if previous_word == 'we':
        value = AFTER_WE.get(word, value)
        contraction = token.replace('’', "'")
        if contraction == "'re":
            value = -3.4
        elif contraction in {"'ve", "'ll"}:
            value = -1.8
    return (doc, word, text[-50:]), value

programs.haiku:
"""Layer 1 MLP down-projection, component 950: a source-code and JSON syntax feature.

In plain terms, this component is negative on programming keywords that begin a line
(import, var, let, using, for, const, function, public, ...), and mildly negative on
keywords used mid-line (param, func, fn, static, const). It is also negative on the
opening brace-quote of a JSON object (' {"'). It is positive on a string value that
opens right after a colon (JSON "key": "value"), on the closing '":' of a JSON key, on
the single-space token after an indentation run, and on zeros: a zero that continues a
run of zeros (as in patent paragraph numbers [0001] or 0000), and a zero after a decimal
point (0.0). A string item opening after a comma is negative.

The program predicts one fixed number for each such pattern, roughly the average
activation of that pattern in training text, and 0 everywhere else. It explains about a
third of the activation's variance; the rest is spread over many tokens with no simple
concept behind them.
"""
READS = ()

# Keywords that open a declaration, import, or control-flow statement.
STRONG_KEYWORDS = {"import", "var", "let", "using", "for", "const", "function", "public"}
LINE_KEYWORDS = STRONG_KEYWORDS | {
    "while", "private", "fn", "from", "class", "try", "if", "def", "switch", "static",
    "int", "void", "export", "pub", "func",
}
# Keywords that appear inside a line of code.
INLINE_KEYWORDS = {"param", "func", "fn", "static", "const"}
# JSON punctuation where a key closes or a string value opens.
JSON_TOKENS = {'":', '":"', ':"', '("', "':", "('", '(\\"', '\\":', '",', '","'}
JSON_OBJECT_OPEN = {' {"', '{"', ' {\\"'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = token.strip()
    line_start = ("\n" in prev) or (prev.strip() == "")

    # Number of zeros in a row ending at this token; the carry resets at each row's start.
    run = (carry or 0) + 1 if token == "0" else 0

    if token == "0":
        if run >= 3:
            value = 1.2      # a zero inside a run of zeros, such as 0000
        elif run == 2:
            value = 0.3
        elif prev == ".":
            value = 0.45     # a zero after a decimal point, as in 0.0
        else:
            value = 0.0
    elif word in LINE_KEYWORDS and line_start:
        value = -1.8 if word in STRONG_KEYWORDS else -0.9
    elif word in INLINE_KEYWORDS:
        value = -0.8
    elif token in JSON_OBJECT_OPEN:
        value = -1.0
    elif token == ' "' and prev.endswith('":'):
        value = 0.9          # a string value after a key
    elif token == ' "' and prev.endswith('",'):
        value = -1.0         # a string item after a comma
    elif token in JSON_TOKENS:
        value = 0.35
    elif token == " " and prev.strip() == "" and "\n" not in prev:
        value = 0.5          # the single-space token after an indentation run
    elif word == "" and line_start:
        value = 0.1          # indentation at the start of a line
    else:
        value = 0.0
    return run, value

programs.sol:
"""A lexical 好 ('good') detector, not a general sentiment detector.

An isolated 好 gives a large negative value. Productive degree/comparison
prefixes and grammatical suffixes attenuate it; lexical compounds are weaker.
A few translations of 'good' and the greeting 'hello' have small responses.
All other tokens receive zero. No earlier-token information is used.
"""
import regex as re

READS = ()


def prefix_scale(text):
    if text in ('', '也'):
        return 1.0
    if text in ('不', '不太'):
        return .85
    if text in ('很', '太', '挺', '真', '还', '就', '做'):
        return .67
    if text in ('最', '更', '越', '较', '比较'):
        return .43
    if text in ('的', '得', '你'):
        return .85
    return None


def good_token(text):
    if '好' not in text:
        return 0.0
    if re.search(r'[\p{Script=Hiragana}\p{Script=Katakana}]', text):
        return 0.0  # Japanese 好き/好み: liking, rather than the adjective
    if text == '好好':  # reduplication
        return -4.8
    match = re.fullmatch(r'(.*?)好([的了地]?)', text)
    if match:
        scale = prefix_scale(match[1])
        if scale is not None:
            suffix = {'': 1.0, '的': .60, '了': .70, '地': .55}
            return -9.6 * scale * suffix[match[2]]
    if text in ('好像', '就好像', '好奇', '偏好'):
        return -.35  # lexicalized senses: seem, curious, preference
    if '良好' in text or '好处' in text or '好运' in text:
        return -1.1
    if text in ('好友', '友好'):
        return -4.2  # friend/friendly compounds
    return -2.7


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].strip()
    value = good_token(text)
    if text in ('いい', '良い', 'よい', '不错'):
        value = -.85
    elif text in ('좋', '좋은', '좋아'):
        value = -2.0
    elif text == 'хорошо':
        value = -1.7
    elif text.lower() == 'hello':
        value = -.8
    elif text.lower() == 'good':
        value = .28
    return None, value

programs.haiku:
"""Chinese 好 ('good', 'well', 'OK') detector.

The component is negative on the character 好 when it is used as the Chinese word for
'good / well / fine' (你好, 不好, 很好, 好的, 最好 ...). It is strongest on a bare 好 or
a token that ends in 好, weaker when 好 starts a longer token, and near zero when the
character is part of a word that does not mean 'good' (好き, 好像, 好奇, 偏好 ...).
A 好 that the tokenizer splits into raw UTF-8 bytes is also caught: the token that
completes the character gets the bare-好 strength.
"""
READS = ()

NOT_GOOD_WORDS = ("好き", "好み", "好像", "好奇", "偏好", "好转", "好感", "好久", "喜好", "好不容易")
COMPARATIVES = ("更好", "最好")


def token_value(tok):
    """Activation for a token whose own text contains 好."""
    if any(w in tok for w in NOT_GOOD_WORDS):
        return -0.5
    if any(w in tok for w in COMPARATIVES):
        return -3.5
    if tok == "好":
        return -9.5
    if tok.endswith("好"):
        return -6.5
    return -3.5


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if "好" in tok:
        return carry, token_value(tok)
    # A token that holds only part of a character decodes to U+FFFD; it can complete a 好.
    if "�" in tok and len(prefix) > 1:
        before = prefix.text_prefixes[-2].count("好")
        if prefix.text_prefixes[-1].count("好") > before:
            return carry, -13.0
    return carry, 0.0

programs.sol:
"""Sparse surface patterns: negative v-er/solve spellings; positive HAVE phrases.

Word fragments are joined so that 'S'+'olving' counts, but 're'+'solving'
does not. Strong negative spellings include ver, solve, silver, liver,
river, lever and Oliver. The ver syllable also transfers to Cyrillic.
Positive values mark HAVE followed by temporal adverbs or no/any, with
separate treatment of contractions, questions and negative auxiliaries.
The remaining rules cover HAVE ... to and repeated middle-dot separators.
Unrecognized tokens receive zero; this is not a semantic problem solver.
"""
import re
from anyascii import anyascii

READS = ()
LETTERS = re.compile(r'[^\W\d_]+$')
SOLVE = re.compile(r'solv(?:e[drs]?|ing|ers?)?$')
VER_RHYMES = {'silver', 'liver', 'river', 'lever', 'oliver'}
ADVERBS = {
    'always': 4.6, 'ever': 4.5, 'never': 2.8,
    'just': 3.8, 'long': 5.0, 'often': 0.7, 'even': 0.6,
    'only': 0.25,
}
HAVE = {'have', 'has', 'had', "'ve", '’ve'}
CONTRACTED = {"'ve", '’ve'}
PRONOUNS = {'i', 'you', 'he', 'she', 'it', 'we', 'they'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', '', 0)
    _, previous, before, tail, dots = carry
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    prev = previous.strip().lower()
    earlier = before.strip().lower()
    match = LETTERS.search(token)
    spelling = match.group().lower() if match else ''
    if token.isalpha():
        spelling = tail + spelling
    spelling = spelling[-40:]
    syllable = anyascii(word)
    old_tail = anyascii(tail)
    value = 0.0

    # Spelling response, with token fragments joined into words.
    if syllable == 'ver':
        value = -2.5
        if token.startswith(' ') and token.strip().islower():
            value = -1.7
        if any(c in spelling for c in 'öäåæø'):
            value = 2.0
        elif spelling == 'unver':
            value = -5.0
        elif token.strip().isupper() and token.startswith(' '):
            value = -0.5
    elif syllable == 'er' and old_tail.endswith('v'):
        value = -1.8
    elif syllable in {'vert', 'vers', 'vere'}:
        value = -0.4
    if SOLVE.fullmatch(spelling):
        value = -3.1
        if token.startswith(' ') and token.strip().islower():
            value = -2.2
        if prev == 'to':
            value = -1.4
        elif prev == 'problem':
            value += 0.8
    elif spelling.rstrip('s') in VER_RHYMES or spelling.endswith('oliver'):
        value = -2.8
        if spelling.rstrip('s') == 'river':
            value = -1.0
        elif spelling.endswith('oliver'):
            value = -4.1
    elif (not token.startswith(' ') and tail
          and re.fullmatch('[aeiou]ver', word)):
        value = -1.8

    # HAVE constructions; ambiguous 's is usually a copula, not HAS.
    auxiliary = prev in HAVE
    scale = 0.8 if prev == 'had' else 1.0
    question = earlier in HAVE and prev in PRONOUNS
    if question:
        auxiliary = True
    if earlier in HAVE and prev == 'not':
        auxiliary, scale = True, 0.5
    if prev in {"'t", '’t'} and earlier in {'haven', 'hasn', 'hadn'}:
        auxiliary, scale = True, 1.5
    if prev in {"'s", '’s', "'d", '’d'} and earlier in PRONOUNS:
        auxiliary = True
        scale = 1.0 if word == 'never' else 0.2
    if auxiliary:
        if word in ADVERBS:
            value = scale * ADVERBS[word]
        elif word in {'no', 'any'}:
            value = 0.4 if word == 'any' or prev == 'has' else 1.1
        if question and word == 'any':
            value = 3.0
        if prev in CONTRACTED:
            if word in {'no', 'not'}:
                value = 7.5
            elif word in {'ever', 'never'}:
                value += 2.0
            elif word in {'only', 'even'}:
                value = 1.7
    if prev in {"'ll", '’ll'}:
        if word in {'ever', 'never'}:
            value = 1.7
        elif word == 'always':
            value = 0.9
    if word == 'to' and earlier in HAVE:
        if prev in {'yet', 'nothing', 'something', 'anything'}:
            value = 2.2
    if word == 'long' and earlier in HAVE and prev == 'a':
        value = 1.5

    dots = dots + len(token) if token and set(token) == {'·'} else 0
    if dots >= 4:
        value = -2.2
    return (doc, token, previous, spelling, dots), value

programs.haiku:
"""layers.1.mlp.down_proj:953, a lexical + perfect-tense component.

What it does, in plain terms:
1. Frequency adverbs placed between a perfect auxiliary and its participle
   ("I've always known", "has never been", "have you ever seen", "I've no problem")
   push it strongly positive (about +4; "no" about +1.5).
2. Words built around "solve" and the spelling "ver" push it negative
   ("solve", "solving", "Solver", "olver", "silver", "river", "Oliver", and the
   word-piece "ver" as in "verbindungen"): about -3 for the solve family, -2 for "ver",
   -1.5 for the river/silver family.
Everything else is predicted as 0. It is a rule over the current token and the
one or two tokens before it, so it reads no hidden state.
"""
READS = ()

# Perfect auxiliaries, including the contracted forms and "haven't"/"hasn't"/"hadn't".
AUX = {"have", "has", "had", "'ve", "’ve", "'d", "’d", "haven", "hasn", "hadn"}
# Adverbs that strongly signal the perfect slot; "no" ("I have no idea") is weaker.
TIME_ADVERBS = {"always", "ever", "never", "long", "just"}
ADVERBS = TIME_ADVERBS | {"no"}
SOLVE_WORDS = {"solve", "solver", "solving", "solved", "solves", "solv", "olve", "olver", "olving"}
VER_FRAGMENT = {"ver"}
RIVER_WORDS = {"silver", "lever", "liver", "river", "rivers", "aver", "iver", "oliver"}


def _norm(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    n = len(toks)
    cur = _norm(toks[-1])

    def back(k):
        # the token k places before the current one, if it belongs to the same document
        if n - 1 - k >= 0 and prefix.document_ids[n - 1 - k] == prefix.document_ids[-1]:
            return _norm(toks[-1 - k])
        return ""

    prev, prev2 = back(1), back(2)
    if prev in {"'t", "’t"}:  # "haven't ever": the auxiliary sits two tokens back
        prev, prev2 = "not", back(2)
    after_aux = prev in AUX or prev2 in AUX  # "have ever" or "have you ever"
    if cur in ADVERBS and after_aux:
        return carry, 4.0 if cur in TIME_ADVERBS else 1.5
    if cur in SOLVE_WORDS:
        return carry, -3.0
    if cur in VER_FRAGMENT:
        return carry, -2.0
    if cur in RIVER_WORDS:
        return carry, -1.5
    return carry, 0.0

programs.sol:
"""Recognize a sparse lexical obtain/ability feature.

Vietnamese được is the largest cue. Weaker cues include Chinese 得,
Japanese potential/passive endings, Thai ได้/ถูก and Korean 되/된.
Kana and adjacent Han characters distinguish Japanese uses of 得.
English get/getters, a few spelling fragments, and document-opening marks
also receive smaller fixed responses.
Unrecognized tokens are zero rather than modeled as lexical noise.
"""
import regex

READS = ()
_KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
_HAN = regex.compile(r'\p{Script=Han}$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    word = s.strip()
    value = 0.0
    if word.casefold() == 'được':
        value = 9.8
    elif word == '得':
        if _KANA.search(recent[-30:]):
            value = 0.9 if _HAN.search(recent) else 4.8
        else:
            value = 0.7
    elif word == 'を得':
        value = 3.5
    elif word == '得意':
        value = 2.3 if _KANA.search(recent[-30:]) else 0.4
    elif word.startswith('得到') or word == 'お得':
        value = 0.7
    elif word == '不得':
        value = 1.2
    elif word in ('获得', '获得了', '獲得', '獲'):
        value = 0.45
    elif word in ('られ', 'られる'):
        value = 1.3
    elif word.startswith('られて'):
        value = 0.5
    elif word == 'ได':
        value = 3.7
    elif word.startswith('้') and recent.endswith('ได'):
        value = 6.8
    elif word == '้':
        value = 0.4
    elif word in ('ถ', 'ูก'):
        value = 1.3
    elif word == 'Đ' or s == ' đ':
        value = 1.0
    elif word == 'đi':
        value = 1.4
    elif word.startswith(('되', '된')):
        value = 0.5
    elif word.startswith('.get'):
        value = 0.24
    elif word == 'get':
        value = 0.07
    elif word == '··':
        value = 0.81
    elif word == 'php' and recent == '<?':
        value = 1.67
    elif word == ':' and recent == 'Title':
        value = -5.6
    return (doc, (recent + s)[-64:]), value

"""Approximate a mostly negative response to 'it' and related spellings.

English it, German es and French il receive the strongest responses. Recent
word frequencies provide language evidence for the ambiguous es/il spellings.
Case, word boundaries and immediate grammatical context adjust the values;
German existential 'gibt/gab es' is weaker. A few other reference words have
small offsets. Embedded it receives a positive suffix value. Unlisted tokens
receive zero, and the short running context resets at each new document.
"""
import math
import re
from wordfreq import zipf_frequency

READS = ()


def language_probability(text, language, alternatives):
    """Compare recent words with competing languages, including English."""
    words = re.findall(r'[^\W\d_]+', text.lower())[-24:]
    advantages = []
    for other in alternatives:
        evidence = 0.0
        for word in words:
            difference = (zipf_frequency(word, language)
                          - zipf_frequency(word, other))
            evidence += max(-3, min(3, difference))
        advantages.append(evidence)
    log_odds = max(-30, min(30, -1.5 + 0.7 * min(advantages)))
    return 1 / (1 + math.exp(-log_odds))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, previous = b'', ''
    else:
        _, history, previous = carry
    token = prefix.token_strings[-1]
    word = token.strip().lstrip(".\"'’“”-_")
    lower = word.lower()
    boundary = not token[:1].isalpha() or not previous[-1:].isalnum()
    before = previous.strip().lower()
    value = 0.0
    if lower == 'it':
        if not boundary:
            value = 0.34
        elif not previous:
            value = (0.55 if token == 'it' else
                     -0.42 if word == 'It' else -0.48)
        elif word == 'It':
            value = -0.9
        elif word == 'IT':
            value = -0.5
        else:
            value = -1.7
            if before == 'what':
                value = -3.6
            elif before == 'when':
                value = -2.45
            elif before in {'make', 'makes', 'made', 'making'}:
                value = -2.75
            elif before in {'which', 'how', 'where'}:
                value = -2.1
            elif before in {'and', 'but', 'or', 'nor', 'yet'}:
                value = -1.05
            elif before in {'because', 'since', 'although', 'though',
                            'unless', 'whether'}:
                value = -1.1
            elif before in {'if', 'then', 'until'}:
                value = -1.4
            elif before == ',':
                value = -1.4
            elif before in {';', ':'}:
                value = -1.1
            elif before in {'to', 'of', 'on', 'in', 'with', 'at', 'as',
                            'by', 'from', 'into', 'onto'}:
                value = -1.35
    elif lower == 'its' and boundary:
        value = -0.35
    elif lower == 'es' and boundary:
        german = language_probability(history.decode('utf8', 'ignore')[-600:],
                                      'de', ('en', 'es', 'fr', 'it', 'pt'))
        strength = 3.7 if before in {'gibt', 'gab', 'gäbe'} else 6.1
        value = (-strength * german - 0.3 * (1 - german)
                 if previous else -0.58)
    elif lower == 'il' and boundary:
        french = 1.0 if any(c in token for c in "'’-") else (
            language_probability(history.decode('utf8', 'ignore')[-600:],
                                 'fr', ('en', 'es', 'it', 'pt')))
        strength = 1.2 if word == 'Il' else 1.6
        if any(c in token for c in "'’-"):
            strength = 1.45
        value = -strength * french
    elif boundary:
        value = {'det': -0.85, 'het': -1.2, 'them': -0.23,
                 'they': -0.08, 'he': -0.025, 'there': -0.09,
                 'this': -0.05}.get(lower, 0.0)
    history = (history + prefix.token_bytes[-1])[-2400:]
    return (doc, history, token), value

programs.haiku:
"""Candidate 2: whole-word pronouns 'it' (and German 'es'), with 'it' after a verb or wh-word stronger."""
from collections.abc import Mapping

READS = ()

# typical activation for each pronoun token (leading space kept; the token decoded alone)
PRONOUN = {" it": -1.6, " It": -0.9, "It": -1.0, " its": -0.3, " them": -0.25, " il": -0.45}
# object-position "it" (after a verb or wh-word) is stronger than subject "it"
OBJECT_PREV = {"what", "make", "makes", "making", "which", "where", "how", "keep", "get", "do", "handle"}
# German function words; a document with several of them is German text
GERMAN = {"und", "der", "die", "das", "ist", "nicht", "ich", "ein", "eine", "mit", "auf", "zu", "den", "dass", "wenn", "auch", "sich", "wir", "sie"}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry["doc"] != doc:
        carry = {"doc": doc, "prev": "", "german": 0}
    prev = carry["prev"]
    if tok.strip().lower() in GERMAN:
        carry["german"] += 1
    value = 0.0
    if tok == " it" and prev in OBJECT_PREV:
        value = -2.5
    elif tok in PRONOUN:
        value = PRONOUN[tok]
    elif tok in (" es", " Es", "Es") and carry["german"] >= 3:
        value = -6.0
    carry["prev"] = tok
    return carry, float(value)

programs.sol:
"""Approximate a patent-drafting contrast using words and short phrases.

Invention/embodiment and descriptive drafting language are positive; numbered
references, publication identifiers and some machinery phrases are negative.
Patent cues set a document-local flag. A short text tail handles split words
and phrase endings; a fading cue handles nearby connective words. Separate
rules cover patent-bibliography labels, the opening Title: label, and
repeated middle-dot separators.
These are lexical approximations, not a general understanding of patents.
"""
import re
READS = ()

# Standalone drafting vocabulary; the second table needs patent context.
LEXICAL = {'apparatus': -0.58,
 'disclose': 0.15,
 'disclosed': 0.24,
 'embodiment': 1.01,
 'embodiments': 0.85,
 'exemplary': 0.62,
 'filing': 0.34,
 'invention': 1.19,
 'plurality': 0.15,
 'schematic': 0.25}
IN_PATENTS = {'al': 0.15,
 'apparatus': -0.43,
 'applications': -0.22,
 'art': 0.94,
 'claim': 0.75,
 'claimed': 0.28,
 'claims': 0.46,
 'composition': -1.37,
 'compositions': -1.2,
 'comprises': 0.61,
 'comprising': 0.32,
 'disclose': 1.0,
 'disclosed': 0.8,
 'disclosure': 0.57,
 'drawings': 1.4,
 'et': -1.28,
 'example': 0.34,
 'examples': 0.22,
 'exemplary': 0.71,
 'filing': 1.82,
 'illustrated': 0.91,
 'method': -1.2,
 'methods': -0.38,
 'particularly': 0.25,
 'preferred': 0.54,
 'relates': 0.19,
 'schematic': 1.14,
 'shown': 0.37,
 'skill': 0.55,
 'skilled': 1.79}
CUES = frozenset("""invention embodiment embodiments wherein thereof
plurality patent""".split())
OFFICES = frozenset("US EP WO CA CN JP DE GB".split())
MACHINERY = r"(?:method|methods|apparatus|process|device|system|systems|arrangement)"


def ends(text, pattern):
    return re.search(pattern + r"\s*$", text) is not None


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, patent, distance, position = "", False, 10000, 0
    else:
        _, tail, patent, distance, position = carry
    text = prefix.token_strings[-1]
    clean = text.strip()
    word = clean.lower()
    before = tail.lower()
    joined = tail + text
    match = re.search(r"([A-Za-z]+)$", joined)
    whole = match.group(1).lower() if match else ""
    if text[-1:].isalpha() and len(clean) >= 3 and whole in CUES:
        word = whole
    citation = re.search(r"(?:US|EP|WO|CA|CN|JP|DE|GB)\d{4,}", joined)
    cue = (word in CUES or clean in {"FIG", "FIGS", "BACKGROUND", "WO", "PCT"}
           or citation or re.search(r"\[0\d{3}\]", joined[-16:]))
    if cue:
        patent, distance = True, 0
    else:
        distance += 1
    near = max(0.0, 1.0 - distance / 48.0)
    value = -0.0016 + LEXICAL.get(word, 0.0)
    if patent:
        value += IN_PATENTS.get(word, 0.0)
        value += near * {"for": -0.34, "and": -0.17, "same": -0.18}.get(word, 0)
        if word == "same":
            value -= 0.14
        if word in {"of", "for", "and"} and ends(before, MACHINERY):
            value += {"of": -0.92, "for": -2.02, "and": -0.82}[word]
        if ends(before, "and"):
            value += {"method": -2.77, "methods": -2.77, "apparatus": -0.66}.get(word, 0)
    if word == "invention":
        if ends(before, "present"):
            value -= 0.19
        if ends(before, r"of(?:\s+the)?"):
            value += 0.52
        if ends(before, r"claim(?:ed)?"):
            value += 3.23
    if word in {"embodiment", "embodiments"}:
        if ends(before, "preferred"):
            value += 0.76
        if ends(before, "(?:one|another|particular)"):
            value += 1.33
    if word == "claim" and ends(before, "(?:regarding|of|in|as)"):
        value += 1.15
    # Patent section headings and illustration references.
    if clean == "BACKGROUND" and position == 0:
        value += 2.07
    if clean == "OF" and ends(before, "background"):
        value += -1.84 if position == 1 else -3.19
    if clean == "DESCRIPTION" and ends(before, "detailed"):
        value += 3.87
    if clean == "VENT" and ends(before, r"\bin"):
        value += 1.75
    if clean == "ION" and before.endswith("invent"):
        value += 0.47
    if whole == "preferred" and clean == "REFERRED":
        value += 1.79
    if whole == "drawings" and clean == "INGS":
        value += 1.16
    if clean in {"FIG", "FIGS", "Fig", "Figs"}:
        value += 0.13 + (0.69 if re.search(r"\n +$", tail) else 0.0)
    if text == "." and ends(before, r"\bfigs?"):
        value += 0.17
    # Numbered patent/application citations.
    if word in {"no", "nos"}:
        if ends(before, r"(?:pat|ser)\."):
            value -= 4.19
            if ends(before, r"ser\."):
                value -= 1.37
        elif ends(before, "(?:application|publication|patent)"):
            value -= 2.39
    if text == ".S":
        value -= 0.17 + (1.06 if patent else 0.0)
    if patent:
        value += {"pat": -0.30, "ser": -0.98}.get(word, 0)
        if text == "." and ends(before, r"(?:\.s|pat|ser|no)"):
            value += 0.59
        boundary = text.startswith(" ") or not tail[-1:].isalpha()
        if clean in OFFICES and boundary:
            value -= 4.0 if clean == "WO" else 3.53
            if clean == "US" and ends(tail, r"\|"):
                value -= 18.64
    # Navigation labels in patent bibliographies (including split words).
    if patent:
        if whole == "classifications" and len(clean) >= 3:
            value = -5.18
        if word == "events" and ends(before, "legal"):
            value = -3.60
        if word == "assignment" and ends(before, "uspto"):
            value = -2.86
        if whole == "espacenet" and len(clean) >= 3:
            value = -1.49
        if word == "by" and ends(before, "referenced"):
            value = -1.94
    # Document-opening formatting effects, separate from patent prose.
    if position == 0:
        value += 0.17
        if clean.isalpha():
            value += 0.09 - (0.14 if clean.istitle() else 0.0)
            value += 0.14 if text.startswith(" ") else 0.0
            value -= 0.06 if clean.isupper() else 0.0
            if word in {"the", "a", "an", "this", "that", "it", "in", "on", "to", "of"}:
                value -= 0.29
        if clean.isdigit():
            value += 0.05
    if position == 0 and text == "BACKGROUND":
        value = 3.07
    if position == 1 and tail == "BACKGROUND" and text.strip() == "OF":
        value = -1.17
    if position == 1 and tail == "Title" and text == ":":
        value = 10.42
    if len(text) >= 2 and set(text) == {"·"}:
        value = 3.17
    return (doc, joined[-160:], patent, distance, position + 1), float(value)

programs.haiku:
"""Patent-language detector for layers.1.mlp.down_proj:957.

What it does: a hand-written, token-level guess at where this MLP output direction is
active in patent text.
- Positive on the words of a patent's description: "invention", "embodiment(s)", "INVENTION"
  split into tokens, and section and figure words ("DESCRIPTION", "BACKGROUND", "FIG",
  "drawings", "comprises", "filing").
- Negative on citation boilerplate ("U.S. Pat. Nos.", "Ser. No.", "US", "Legal Events"),
  more strongly when the nearby text is already patent text.
- Mildly negative on process nouns ("method", "composition") and the preposition after them.
Otherwise 0. Patent text is detected as >= 3 patent words in the last 40 tokens of the same document.
"""
READS = ()
WINDOW = 40
PATENT_WORDS = {"invention", "Invention", "vention", "VENT", "ION", "embodiment", "embodiments",
    "patent", "claim", "claims", "FIG", "US", "U.S", "Pat", "No", "Nos", "drawings",
    "DESCRIPTION", "BACKGROUND", "method", "comprises", "present", "apparatus", "device"}
INVENTION_WORDS = {"invention", "Invention", "vention", "VENT", "ION", "embodiment", "embodiments"}
SECTION_WORDS = {"DESCRIPTION", "BACKGROUND", "REFERRED", "FIG", "drawings", "illustrated",
    "schematic", "exemplary", "filing", "comprises", "claim", "aspect", "shown"}
CITATION_WORDS = {"Nos", "No", "US", ".S", "States", "Events", "ifications", "Assignment"}
PROCESS_WORDS = {"method", "methods", "composition", "compositions", "apparatus", "supervisor", "device"}
PREPOSITIONS = {"for", "of", "and", "OF", "et", "to"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else []
    word = prefix.token_strings[-1].strip()
    recent = (recent + [word in PATENT_WORDS])[-WINDOW:]
    patent_text = sum(recent) >= 3
    value = 0.0
    if word in INVENTION_WORDS:
        value = 1.15 + (0.09 if patent_text else 0.0)
    elif word in SECTION_WORDS:
        value = 0.34 + (0.48 if patent_text else 0.0)
    elif word in CITATION_WORDS:
        value = -0.37 + (-1.2 if patent_text else 0.0)
    elif word in PROCESS_WORDS:
        value = -0.2 + (-0.27 if patent_text else 0.0)
    elif word in PREPOSITIONS:
        after_process = len(prefix.token_strings) > 1 and prefix.token_strings[-2].strip() in PROCESS_WORDS
        value = (-0.14 if patent_text else 0.0) + (-0.24 if after_process else 0.0)
    return (doc, recent), float(value)

programs.sol:
"""A document-onset impulse, scaled by the kind of token.

Emit a response while the prefix contains only one distinct token. Otherwise
emit zero. At onset, lexical tokens receive a positive response; very common
English words, punctuation, whitespace, and digits receive smaller responses.
The length and frequency rules approximate the large lexical variation at
onsets without storing individual token activations.
"""
from functools import lru_cache
import unicodedata
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=8192)
def onset(text):
    word = text.strip()
    if text == '<|im_start|>':
        return 3.46
    if not word:
        return -0.2
    if not word.isalpha():
        # Code fragments can contain letters beside punctuation.
        if any('LATIN' in unicodedata.name(ch, '') for ch in word):
            return 1.1
        return -0.25
    frequency = zipf_frequency(word, 'en')
    if len(word) <= 5:
        if frequency >= 6.7:
            return 0.28 if word.istitle() else -0.86
        return 1.45 if frequency < 4.2 else 0.99
    if frequency < 3.8:
        return 2.07
    return 1.27 if len(word) <= 8 else 1.69


def step(carry, prefix, upstream):
    token = prefix.token_ids[-1]
    first = (len(prefix.token_ids) == 1 or
             prefix.document_ids[-1] != prefix.document_ids[-2])
    if not first and carry != token:
        return None, 0.0
    return token, onset(prefix.token_strings[-1])
